(function(A){Object.assign(A.D,{"G433":{"l":"ἀνήκω","o":3,"ar":"<f><o>ἀν-ήκω</o></f> <s>أصلاً: <b>يكون قد بلغ إلى</b>؛ وعند المتأخرين، غير شخصي: <b>يليق</b>، <b>يجب، ينبغي</b>: بالمعنى الأخلاقي، <r v=\"Eph.5.4\"></r>، <r v=\"Col.3.18\"></r>؛ <g>τὸ ἀνῆκον</g> (ما يليق)، <r v=\"Phlm.1.8\"></r>.†</s>","en":"<f><o>ἀν-ήκω</o></f> <et> <e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>ἥκω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Josh.23.14\"></r> (<h n=\"H935\">בּוֹא</h>), <r v=\"1Sam.27.8\"></r>, <r v=\"SirP.1.10\"></r>, I, II Mac<i>6</i>*;]</e> </et> <s>prop., <b>to have come up to</b>; in later writers, impers. <b>it is due</b>, <b>it is befitting</b>: in ethical sense (MM, <i>VGT</i>, s.v.), <r v=\"Eph.5.4\"></r>, <r v=\"Col.3.18\"></r>; <g>τὸ ἀνῆκον</g>, <r v=\"Phlm.1.8\"></r>.†</s>"},"G444":{"l":"ἄνθρωπος","o":550,"ar":"<f><o>ἄνθρωπος</o>، <g>-ου, ὁ</g>،</f> <s><b>إنسان</b>: <s n=\"1.\">بالمعنى العام، كائن بشري، ذكرًا كان أو أنثى (باللاتينية <l>homo</l>): <r v=\"John.16.21\"></r>؛ مع أداة التعريف، <r v=\"Matt.4.4\"></r> <r v=\"Matt.12.35\"></r>، <r v=\"Mark.2.27\"></r>، <r v=\"John.2.25\"></r>، <r v=\"Rom.7.1\"></r>، وفي مواضع أخرى؛ تمييزًا له عن الله، <r v=\"Matt.19.6\"></r>، <r v=\"John.10.33\"></r>، <r v=\"Col.3.23\"></r>، وفي مواضع أخرى؛ وعن الحيوانات إلخ، <r v=\"Matt.4.19\"></r>، <r v=\"Luke.5.10\"></r>، <r v=\"Rev.9.4\"></r>، وفي مواضع أخرى؛ متضمنًا الضعف والنقص البشريين، <r v=\"1Cor.3.4\"></r>؛ <g>σοφία ἀνθρώπων</g>، <r v=\"1Cor.2.5\"></r>؛ <g>ἀνθρώπων ἐπιθυμίαι</g>، <r v=\"1Pet.4.2\"></r>؛ <g>κατὰ ἄνθρωπον περιπατεῖν</g>، <r v=\"1Cor.3.3\"></r>؛ <g>κατὰ ἄ. λέγειν</g> (<g>λαλεῖν</g>)، <r v=\"Rom.3.5\"></r>، <r v=\"1Cor.9.8\"></r>؛ <g>κατὰ ἄ- λέγειν</g>، <r v=\"Gal.3.15\"></r> (قارن <r v=\"1Cor.15.32\"></r>، <r v=\"Gal.1.11\"></r>)؛ وكنايةً، عن طبيعة الإنسان أو حاله، <g>ὁ ἔσω</g> (<g>ἔξω</g>) <g>ἄ.</g>، <r v=\"Rom.7.22\"></r>، <r v=\"Eph.3.16\"></r>، <r v=\"2Cor.4.16\"></r> (قارن <r v=\"1Pet.3.4\"></r>)؛ <g>ὁ παλαιὸς</g>، <g>καινὸς</g>، <g>νέος ἄ.</g>، <r v=\"Rom.6.6\"></r>، <r v=\"Eph.2.15\"></r> <r v=\"Eph.4.22\"></r>، <r v=\"Eph.4.24\"></r>، <r v=\"Col.3.9\"></r>، <r v=\"Col.3.10\"></r>؛ مقرونًا باسم آخر، <g>ἄ. ἔμπορος</g>، <b>تاجر</b>، <r v=\"Matt.13.45\"></r>؛ <g>οἰκοδεσπότης</g>، <r v=\"Matt.13.52\"></r>؛ <g>βασιλεύς</g>، <r v=\"Matt.18.23\"></r>؛ <g>φάγος</g>، <r v=\"Matt.11.19\"></r>؛ مع اسم أمة، <g>Κυρηναῖος</g>، <r v=\"Matt.27.32\"></r>؛ <g>Ἰουδαῖος</g>، <r v=\"Acts.21.39\"></r>؛ <g>Ῥωμαῖος</g>، <r v=\"Acts.16.37\"></r>؛ جمع <g>οἱ ἄ.</g>، <b>الناس</b>، <b>البشر</b>: <r v=\"Matt.5.13\"></r>، <r v=\"Matt.5.16\"></r>، <r v=\"Mark.8.24\"></r>، <r v=\"John.4.28\"></r>؛ <g>οὐδεὶς ἀνθρώπων</g>، <r v=\"Mark.11.2\"></r>، <r v=\"1Tim.6.16\"></r>.</s> <s n=\"2.\">بمعنى النكرة، <g>ἄ.</g> = <g>τις</g>، <b>أحدٌ ما</b>، <b>إنسان (ما)</b>: <r v=\"Matt.17.14\"></r>، <r v=\"Mark.12.1\"></r>، وفي مواضع أخرى؛ <g>τις ἄ.</g>، <r v=\"Matt.18.12\"></r>، <r v=\"John.5.5\"></r>، وفي مواضع أخرى؛ نكرة بمعنى <b>المرء</b> (بالفرنسية <l>on</l>)، <r v=\"Rom.3.28\"></r>، <r v=\"Gal.2.16\"></r>، وفي مواضع أخرى؛ عكس النساء والعبيد إلخ، <r v=\"Matt.10.36\"></r> <r v=\"Matt.19.10\"></r>، <r v=\"John.7.22\"></r>، <r v=\"John.7.23\"></r>.</s> <s n=\"3.\">بمعنى المعرفة، مع أداة التعريف، عن شخص معيّن؛ <r v=\"Matt.12.13\"></r>، <r v=\"Mark.3.5\"></r>، وفي مواضع أخرى؛ <g>οὗτος ὁ ἄ.</g>، <r v=\"Luke.14.30\"></r>؛ <g>ὁ ἄ οὗτος</g>، <g>ἐκεῖνος</g>، <r v=\"Mark.14.71\"></r>، <r v=\"Matt.12.45\"></r>؛ <g>ὁ ἄ. τ. ἀνομίας</g>، <r v=\"2Thess.2.3\"></r>؛ <g>ἄ τ. θεοῦ</g> (عن العبرية <h n=\"H430\">אֱלֹהִים</h> <h n=\"H376\">אִישׁ</h>)، <r v=\"1Tim.6.11\"></r>، <r v=\"2Tim.3.17\"></r>، <r v=\"2Pet.1.21\"></r>؛ <g>ὁ υἱὸς τοῦ ἀ.</g>، انظر تحت مدخل <g>υἱός</g>.</s> </s>","en":"<f><o>ἄνθρωπος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H120\">אָדָם</h>, <h n=\"H376\">אִישׁ</h>, also for <h n=\"H582\">אֱנוֹשׁ</h>, etc.;]</e> </et> <s><b>man</b>: <s n=\"1.\">generically, a human being, male or female (Lat. <l>homo</l>): <r v=\"John.16.21\"></r>; c. art., <r v=\"Matt.4.4\"></r> <r v=\"Matt.12.35\"></r>, <r v=\"Mark.2.27\"></r>, <r v=\"John.2.25\"></r>, <r v=\"Rom.7.1\"></r>, al; disting. from God, <r v=\"Matt.19.6\"></r>, <r v=\"John.10.33\"></r>, <r v=\"Col.3.23\"></r>, al.; from animals, etc., <r v=\"Matt.4.19\"></r>, <r v=\"Luke.5.10\"></r>, <r v=\"Rev.9.4\"></r>, al.; implying human frailty and imperfection, <r v=\"1Cor.3.4\"></r>; <g>σοφία ἀνθρώπων</g>, <r v=\"1Cor.2.5\"></r>; <g>ἀνθρώπων ἐπιθυμίαι</g>, <r v=\"1Pet.4.2\"></r>; <g>κατὰ ἄνθρωπον περιπατεῖν</g>, <r v=\"1Cor.3.3\"></r>; <g>κατὰ ἄ. λέγειν</g> (<g>λαλεῖν</g>), <r v=\"Rom.3.5\"></r>, <r v=\"1Cor.9.8\"></r>; <g>κατὰ ἄ- λέγειν</g>, <r v=\"Gal.3.15\"></r> (cf. <r v=\"1Cor.15.32\"></r>, <r v=\"Gal.1.11\"></r>); by meton., of man's nature or condition, <g>ὁ ἔσω</g> (<g>ἔξω</g>) <g>ἄ.</g>, <r v=\"Rom.7.22\"></r>, <r v=\"Eph.3.16\"></r>, <r v=\"2Cor.4.16\"></r> (cf. <r v=\"1Pet.3.4\"></r>); <g>ὁ παλαιὸς</g>, <g>καινὸς</g>, <g>νέος ἄ.</g>, <r v=\"Rom.6.6\"></r>, <r v=\"Eph.2.15\"></r> <r v=\"Eph.4.22\"></r>, <r v=\"Eph.4.24\"></r>, <r v=\"Col.3.9\"></r>, <r v=\"Col.3.10\"></r>; joined with another subst., <g>ἄ. ἔμπορος</g>, <b>a merchant</b>, <r v=\"Matt.13.45\"></r> (WH, txt. om. <g>ἄ.</g>); <g>οἰκοδεσπότης</g>, <r v=\"Matt.13.52\"></r>; <g>βασιλεύς</g>, <r v=\"Matt.18.23\"></r>; <g>φάγος</g>, <r v=\"Matt.11.19\"></r>; with name of nation, <g>Κυρηναῖος</g>, <r v=\"Matt.27.32\"></r>; <g>Ἰουδαῖος</g>, <r v=\"Acts.21.39\"></r>; <g>Ῥωμαῖος</g>, <r v=\"Acts.16.37\"></r>; pl. <g>οἱ ἄ.</g>, <b>men</b>, <b>people</b>: <r v=\"Matt.5.13\"></r>, <r v=\"Matt.5.16\"></r>, <r v=\"Mark.8.24\"></r>, <r v=\"John.4.28\"></r>; <g>οὐδεὶς ἀνθρώπων</g>, <r v=\"Mark.11.2\"></r>, <r v=\"1Tim.6.16\"></r>.</s> <s n=\"2.\">Indef., <g>ἄ.</g> = <g>τις</g>, <b>some one</b>, <b>a man</b>: <r v=\"Matt.17.14\"></r>, <r v=\"Mark.12.1\"></r>, al.; <g>τις ἄ.</g>, <r v=\"Matt.18.12\"></r>, <r v=\"John.5.5\"></r>, al.; indef. <b>one</b> (Fr. <l>on</l>), <r v=\"Rom.3.28\"></r>, <r v=\"Gal.2.16\"></r>, al.; opp. to women, servants, etc., <r v=\"Matt.10.36\"></r> <r v=\"Matt.19.10\"></r>, <r v=\"John.7.22\"></r>, <r v=\"John.7.23\"></r>.</s> <s n=\"3.\">Definitely, c. art., of some particular person; <r v=\"Matt.12.13\"></r>, <r v=\"Mark.3.5\"></r>, al.; <g>οὗτος ὁ ἄ.</g>, <r v=\"Luke.14.30\"></r>; <g>ὁ ἄ οὗτος</g>, <g>ἐκεῖνος</g>, <r v=\"Mark.14.71\"></r>, <r v=\"Matt.12.45\"></r>; <g>ὁ ἄ. τ. ἀνομίας</g>, <r v=\"2Thess.2.3\"></r>; <g>ἄ τ. θεοῦ</g> (of Heb. <h n=\"H430\">אֱלֹהִים</h> <h n=\"H376\">אִישׁ</h>), <r v=\"1Tim.6.11\"></r>, <r v=\"2Tim.3.17\"></r>, <r v=\"2Pet.1.21\"></r>; <g>ὁ υἱὸς τοῦ ἀ.</g>, v.s. <g>υἱός</g>.</s> </s> <sy><i>SYN.</i>: <x><g>ἀνήρ</g></x>, q.v. (and cf. MM, <i>VGT</i>, 44; Cremer, 103, 635).</sy>"},"G417":{"l":"ἄνεμος","o":31,"ar":"<f><o>ἄνεμος</o>، <g>-ου, ὁ</g></f> <s><b>ريح</b>: <r v=\"Matt.11.7\"></r> <r v=\"Matt.14.24\"></r>، <r v=\"Matt.14.30\"></r>، <r v=\"Matt.14.32\"></r>، <r v=\"Mark.4.37\"></r>، <r v=\"Mark.4.39\"></r>، <r v=\"Mark.4.41\"></r> <r v=\"Mark.6.48\"></r>، <r v=\"Mark.6.51\"></r>، <r v=\"Luke.7.24\"></r> <r v=\"Luke.8.23\"></r>، <r v=\"Luke.8.24\"></r>، <r v=\"John.6.13\"></r>، <r v=\"Acts.27.7\"></r>، <r v=\"Acts.27.14\"></r>، <r v=\"Acts.27.15\"></r>، <r v=\"Jas.3.4\"></r>، <r v=\"Rev.6.13\"></r> <r v=\"Rev.7.1\"></r>؛ جمع، <r v=\"Matt.7.25\"></r>، <r v=\"Matt.7.27\"></r> <r v=\"Matt.8.26\"></r>، <r v=\"Matt.8.27\"></r>، <r v=\"Luke.8.25\"></r>، <r v=\"Acts.27.4\"></r>، <r v=\"Jude.1.12\"></r>؛ <g>οἱ τέσσαρες ἄ. τῆς γῆς</g>، <r v=\"Rev.7.1\"></r>؛ ومن ثمّ جهات السماء الأربع، <r v=\"Matt.24.31\"></r>، <r v=\"Mark.13.27\"></r>؛ مجازيًا، عن التعليم المتقلّب، <r v=\"Eph.4.14\"></r>.†</s>","en":"<f><o>ἄνεμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7307\">רוּחַ</h>;]</e> </et> <s><b>wind</b>: <r v=\"Matt.11.7\"></r> <r v=\"Matt.14.24\"></r>, <r v=\"Matt.14.30\"></r>, <r v=\"Matt.14.32\"></r>, <r v=\"Mark.4.37\"></r>, <r v=\"Mark.4.39\"></r>, <r v=\"Mark.4.41\"></r> <r v=\"Mark.6.48\"></r>, <r v=\"Mark.6.51\"></r>, <r v=\"Luke.7.24\"></r> <r v=\"Luke.8.23\"></r>, <r v=\"Luke.8.24\"></r>, <r v=\"John.6.13\"></r>, <r v=\"Acts.27.7\"></r>, <r v=\"Acts.27.14\"></r>, <r v=\"Acts.27.15\"></r>, <r v=\"Jas.3.4\"></r>, <r v=\"Rev.6.13\"></r> <r v=\"Rev.7.1\"></r>; pl., <r v=\"Matt.7.25\"></r>, <r v=\"Matt.7.27\"></r> <r v=\"Matt.8.26\"></r>, <r v=\"Matt.8.27\"></r>, <r v=\"Luke.8.25\"></r>, <r v=\"Acts.27.4\"></r>, <r v=\"Jude.1.12\"></r>; <g>οἱ τέσσαρες ἄ. τῆς γῆς</g>, <r v=\"Rev.7.1\"></r>; hence the four quarters of the heavens (v. Deiss., <i>BS</i>, 248; MM, <i>VGT</i>, s.v.), <r v=\"Matt.24.31\"></r>, <r v=\"Mark.13.27\"></r>; metaph., of variable teaching, <r v=\"Eph.4.14\"></r>.†</s> <sy><i>SYN.</i>: <x><g>πνεῦμα</g></x>, <x><g>πνοή</g></x> (and cf. <x><g>θύελλα</g></x>, <x><g>λαῖλαψ</g></x>).</sy>"},"G441":{"l":"ἀνθρωπάρεσκος","o":2,"ar":"<f>† <o>ἀνθρωπ-άρεσκος</o>، <g>-ον</g></f> <s><b>ساعٍ إلى إرضاء الناس</b>: <r v=\"Eph.6.6\"></r>، <r v=\"Col.3.22\"></r>.†</s>","en":"<f>† <o>ἀνθρωπ-άρεσκος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<x><g>ἄνθρωπος</g></x>, <x><g>ἄρεσκος</g></x>, <i>pleasing</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.53.5\"></r>*;]</e> </et> <s><b>studying to please men</b>: <r v=\"Eph.6.6\"></r>, <r v=\"Col.3.22\"></r> (Cremer, 642; MM, <i>VGT</i>, s.v.).†</s>"},"G450":{"l":"ἀνίστημι","o":115,"ar":"<f><o>ἀν-ίστημι</o></f> <s n=\"1.\">سببي، في المستقبل والماضي البسيط الأول المبني للمعلوم، مع المنصوب، <b>يُقيم</b>: <r v=\"Acts.9.41\"></r>؛ من الموت، <r v=\"John.6.39\"></r>، <r v=\"Acts.2.32\"></r>؛ <b>يُقيم</b>، <b>يجعله يولد أو يظهر</b>: <r v=\"Matt.22.24\"></r>، <r v=\"Acts.3.22\"></r>، <r v=\"Acts.3.26\"></r>.</s> <s n=\"2.\">لازم، في الصيغة الوسطى والماضي البسيط الثاني المبني للمعلوم؛ <s n=\"(a)\"><b>يقوم</b>: من الاضطجاع، <r v=\"Mark.1.35\"></r>؛ من الجلوس، <r v=\"Luke.4.16\"></r>؛ لمغادرة مكان، <r v=\"Matt.9.9\"></r>؛ على سبيل الحشو، كالعبرية <h n=\"H6965\">קוּם</h>، قبل أفعال الذهاب، <r v=\"Mark.10.1\"></r>، وفي مواضع أخرى؛ عن الأموات، <r v=\"Matt.17.23\"></r>، <r v=\"Mark.8.31\"></r>؛ يليه <g>ἐκ νεκρῶν</g>، <r v=\"Matt.17.9\"></r>، <r v=\"Mark.9.9\"></r>؛</s> <s n=\"(b)\"><b>يقوم (ينهض)</b>، <b>يظهر</b>: <r v=\"Acts.5.36\"></r>، <r v=\"Rom.15.12\"></r>.</s> </s>","en":"<f><o>ἀν-ίστημι</o></f> <et><e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>ἵστημι</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6965\">קוּם</h>;]</e> </et> <s n=\"1.\">causal, in fut. and 1 aor. act., c. acc., <b>to raise up</b>: <r v=\"Acts.9.41\"></r>; from death, <r v=\"John.6.39\"></r>, <r v=\"Acts.2.32\"></r>; <b>to raise up</b>, <b>cause to be born or appear</b>: <r v=\"Matt.22.24\"></r>, <r v=\"Acts.3.22\"></r>, <r v=\"Acts.3.26\"></r>.</s> <s n=\"2.\">Intrans., in mid. and 2 aor act.; <s n=\"(a)\"><b>to rise</b>: from lying, <r v=\"Mark.1.35\"></r>; from sitting, <r v=\"Luke.4.16\"></r>; to leave a place, <r v=\"Matt.9.9\"></r>; pleonastically, as Heb. <h n=\"H6965\">קוּם</h>, before verbs of going, <r v=\"Mark.10.1\"></r>, al. (v. Dalman, <i>Words</i>, 23; M, <i>Pr.</i>, 14); of the dead, <r v=\"Matt.17.23\"></r>, <r v=\"Mark.8.31\"></r>; seq. <g>ἐκ νεκρῶν</g>, <r v=\"Matt.17.9\"></r>, <r v=\"Mark.9.9\"></r>;</s> <s n=\"(b)\"><b>to arise</b>, <b>appear</b>: <r v=\"Acts.5.36\"></r>, <r v=\"Rom.15.12\"></r> (cf. <g>ἐπ-</g>, <g>ἐξ- ἀνίστημι</g>, and v. Cremer, 306, 738; MM, <i>VGT</i>, s.v.).</s> </s> <sy><i>SYN.</i>: <x><g>ἐγείρω</g></x>.</sy>"},"G435":{"l":"ἀνήρ","o":216,"ar":"<f><o>ἀνήρ</o>، <x><g>ἀνδρός</g></x>، <g>ὁ</g>،</f> <s><b>رجل</b>، باللاتينية <l>vir.</l> <s n=\"1.\">عكس المرأة، <r v=\"Acts.8.12\"></r>، <r v=\"1Tim.2.12\"></r>؛ وبمعنى <b>زوج</b>، <r v=\"Matt.1.16\"></r>، <r v=\"John.4.16\"></r>، <r v=\"Rom.7.2\"></r>، <r v=\"Titus.1.6\"></r>.</s> <s n=\"2.\">عكس الصبي أو الطفل، <r v=\"1Cor.13.11\"></r>، <r v=\"Eph.4.13\"></r>، <r v=\"Jas.3.2\"></r>.</s> <s n=\"3.\">بدلاً من اسم أو صفة، مثل <g>ἀ. ἁμαρτωλός</g>، <r v=\"Luke.5.8\"></r>؛ <g>ἀ. προφήτης</g>، <r v=\"Luke.24.19\"></r>؛ وكثيرًا في صيغ الخطاب، مثل <g>ἀ. ἀδελφοί</g>، <r v=\"Acts.1.16\"></r>؛ وخاصةً مع أسماء الأمم، مثل <g>ἀ. Ἰουδαῖος</g>، <r v=\"Acts.22.3\"></r>؛ <g>ἀ. Ἐφέσιοι</g>، <r v=\"Acts.19.35\"></r>.</s> <s n=\"4.\">بوجه عام، <b>رجل</b>، <b>شخص ذكر</b>: = <g>τις</g>، <r v=\"Luke.8.41\"></r>، <r v=\"Acts.6.11\"></r>.</s> </s>","en":"<f><o>ἀνήρ</o>, <x><g>ἀνδρός</g></x>, <g>ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H376\">אִישׁ</h>, freq. <h n=\"H582\">אֱנוֹשׁ</h>, also <h n=\"H120\">אָדָם</h>, etc.;]</e> </et> <s><b>a man</b>, Lat. <l>vir.</l> <s n=\"1.\">As opp. to a woman, <r v=\"Acts.8.12\"></r>, <r v=\"1Tim.2.12\"></r>; as a <b>husband</b>, <r v=\"Matt.1.16\"></r>, <r v=\"John.4.16\"></r>, <r v=\"Rom.7.2\"></r>, <r v=\"Titus.1.6\"></r>.</s> <s n=\"2.\">As opp. to a boy or infant, <r v=\"1Cor.13.11\"></r>, <r v=\"Eph.4.13\"></r>, <r v=\"Jas.3.2\"></r>.</s> <s n=\"3.\">In appos. with a noun or adj., as <g>ἀ. ἁμαρτωλός</g>, <r v=\"Luke.5.8\"></r>; <g>ἀ. προφήτης</g>, <r v=\"Luke.24.19\"></r>; freq. in terms of address, as <g>ἀ. ἀδελφοί</g>, <r v=\"Acts.1.16\"></r>; and esp. with gentilic names, as <g>ἀ. Ἰουδαῖος</g>, <r v=\"Acts.22.3\"></r>; <g>ἀ. Ἐφέσιοι</g>, <r v=\"Acts.19.35\"></r>.</s> <s n=\"4.\">In general, <b>a man</b>, <b>a male person</b>: = <g>τις</g>, <r v=\"Luke.8.41\"></r>, <r v=\"Acts.6.11\"></r>.</s> </s> <sy><i>SYN.</i>: <x><g>ἄνθρωπος</g></x>, q.v. (cf. MM, <i>VGT</i>, s.v.).</sy>"},"G447":{"l":"ἀνίημι","o":4,"ar":"<f><o>ἀν-ίημι</o></f> <s n=\"1.\"><b>يرسل إلى فوق</b>، <b>يُخرج (يُنتج)</b>، <b>يردّ (يرسل راجعًا)</b>.</s> <s n=\"2.\"><b>يترك</b>، أي يدع بلا سند: <r v=\"Heb.13.5\"></r> (قارن <r v=\"Deut.31.6\"></r>).</s> <s n=\"3.\"><b>يُرخي</b>، <b>يحلّ (يفكّ)</b>: <r v=\"Acts.16.26\"></r> <r v=\"Acts.27.40\"></r>؛ ومن ثمّ مجازيًا، <b>يترك</b>، <b>يكفّ عن</b>: <r v=\"Eph.6.9\"></r>.†</s>","en":"<f><o>ἀν-ίημι</o></f> <et> <e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>ἵημι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7503\">רפה</h>, <h n=\"H5375\">נשׂא</h>, etc.;]</e> </et> <s n=\"1.\"><b>to send up</b>, <b>produce</b>, <b>to send back</b>.</s> <s n=\"2.\"><b>to let go</b>, leave without support: <r v=\"Heb.13.5\"></r> (cf. <r v=\"Deut.31.6\"></r>; Hom., <i>Il.</i>, ii, 71).</s> <s n=\"3.\"><b>to relax</b>, <b>loosen</b> (v. Field, <i>Notes</i>, 124 f.): <r v=\"Acts.16.26\"></r> <r v=\"Acts.27.40\"></r>; hence, metaph., <b>to give up</b>, <b>desist from</b>: <r v=\"Eph.6.9\"></r>.†</s>"},"G421":{"l":"ἀνεξιχνίαστος","o":2,"ar":"<f>† <o>ἀνεξιχνίαστος</o>، <g>-ον</g></f> <s><b>لا يُستقصى، لا يُتتبَّع أثره</b>: <r v=\"Rom.11.33\"></r>، <r v=\"Eph.3.8\"></r>.†</s>","en":"<f>† <o>ἀνεξιχνίαστος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>ἐξιχνιάζω</g></x>, <i>to track out</i>; &lt; <x><g>ἴχνος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.5.9\"></r> <r v=\"Job.9.10\"></r> <r v=\"Job.34.24\"></r> (<h n=\"H2714\">חֵקֶר</h> <h n=\"H369\">אֵין</h>)*;]</e> </et> <s><b>that cannot be traced out</b>: <r v=\"Rom.11.33\"></r>, <r v=\"Eph.3.8\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G473":{"l":"ἀντί","o":22,"ar":"<f><o>ἀντί</o></f> <s n=\"1.\">أصلاً، بالمعنى المكاني، <b>تجاه</b>، <b>مقابل</b>، ومن ثمّ؛</s> <s n=\"2.\"><b>بدلاً من</b>، <b>عوضًا عن</b>، <b>عن</b> : <r v=\"Matt.5.38\"></r> <r v=\"Matt.17.27\"></r>، <r v=\"Luke.11.11\"></r>، <r v=\"1Cor.11.15\"></r>، <r v=\"Heb.12.2\"></r>؛ مع المصدر المعرَّف بالأداة، <r v=\"Jas.4.15\"></r>؛ عن التعاقب (الخلافة)، <r v=\"Matt.2.22\"></r>؛ <g>χάριν ἀ. χάριτος</g>، <r v=\"John.1.16\"></r>؛ عن الثمن في المبادلة، <r v=\"Heb.12.16\"></r>؛ <g>λύτρον ἀ. πολλῶν</g>، <r v=\"Matt.20.28\"></r>، <r v=\"Mark.10.45\"></r>؛ عن المجازاة، <r v=\"Rom.12.17\"></r>، <r v=\"1Thess.5.15\"></r>، <r v=\"1Pet.3.9\"></r> (قارن <r v=\"Wis.11.15\"></r>)؛ <g>ἀνθ᾽ ὧν</g>، <b>لأنّ</b>، <r v=\"Luke.1.20\"></r> <r v=\"Luke.19.44\"></r>، <r v=\"Acts.12.23\"></r>، <r v=\"2Thess.2.10\"></r>؛ وكذلك بمعنى لذلك، <r v=\"Luke.12.3\"></r>؛ <g>ἀ. τούτου</g> (السبعينية ترجمةً لـ <h n=\"H5921,H3653\">עַל־כֵּן</h>)، <r v=\"Eph.5.31\"></r>. وكسابقة، <g>ἀντι-</g> (قبل حروف العلة <g>ἀντ-</g>، <g>ἀνθ᾽-</g>)، تدل على <s n=\"(a)\"><b>المقابلة</b>، <g>ἀντιπέραν</g>؛</s> <s n=\"(b)\">التعاون، <g>ἀντιβάλλειν</g>؛</s> <s n=\"(c)\">المجازاة، <g>ἀντιμισθία</g>؛</s> <s n=\"(d)\">المعارضة، <g>ἀντίχριστος</g>؛</s> <s n=\"(e)\">الإحلال (النيابة)، <g>ἀνθύπατος</g>. والأفعال المركّبة مع <g>ἀ.</g> تتعدّى عادةً بالقابل .†</s> </s>","en":"<f><o>ἀντί</o></f> <et> <e t=\"derivation\">(the <g>ι</g> is elided only in <g>ἀνθ᾽ ὧν</g>), prep. c. gen. (cf. MM, <i>VGT</i>, s.v.);</e> </et> <s n=\"1.\">prop, in local sense, <b>over against</b>, <b>opposite</b>, hence;</s> <s n=\"2.\"><b>instead of</b>, <b>in place of</b>, <b>for</b> (Hom., etc.): <r v=\"Matt.5.38\"></r> <r v=\"Matt.17.27\"></r>, <r v=\"Luke.11.11\"></r>, <r v=\"1Cor.11.15\"></r>, <r v=\"Heb.12.2\"></r>; c. artic. inf. (cl.), <r v=\"Jas.4.15\"></r>; of succession, <r v=\"Matt.2.22\"></r>; <g>χάριν ἀ. χάριτος</g>, <r v=\"John.1.16\"></r> (M, <i>Pr.</i>, 100); of price in exchange, <r v=\"Heb.12.16\"></r>; <g>λύτρον ἀ. πολλῶν</g>, <r v=\"Matt.20.28\"></r>, <r v=\"Mark.10.45\"></r> (M, <i>Pr.</i>, 105); of requital, <r v=\"Rom.12.17\"></r>, <r v=\"1Thess.5.15\"></r>, <r v=\"1Pet.3.9\"></r> (cf. <r v=\"Wis.11.15\"></r>); <g>ἀνθ᾽ ὧν</g>, <b>because</b>, <r v=\"Luke.1.20\"></r> <r v=\"Luke.19.44\"></r>, <r v=\"Acts.12.23\"></r>, <r v=\"2Thess.2.10\"></r> (cl., LXX for <h n=\"H834\">אֲשֶׁר</h> <h n=\"H8478\">תַּחַת</h>); id. therefore (cl., LXX), <r v=\"Luke.12.3\"></r>; <g>ἀ. τούτου</g> (LXX for <h n=\"H5921,H3653\">עַל־כֵּן</h>), <r v=\"Eph.5.31\"></r>. As a prefix, <g>ἀντι-</g> (before vowels <g>ἀντ-</g>, <g>ἀνθ᾽-</g>), denotes <s n=\"(a)\"><b>over against</b>, <g>ἀντιπέραν</g>;</s> <s n=\"(b)\">co-operation, <g>ἀντιβάλλειν</g>;</s> <s n=\"(c)\">requital, <g>ἀντιμισθία</g>;</s> <s n=\"(d)\">opposition, <g>ἀντίχριστος</g>;</s> <s n=\"(e)\">substitution, <g>ἀνθύπατος</g>. Compounds of <g>ἀ.</g> usually govern dat. (Bl., § 37, 7).†</s> </s>"},"G430":{"l":"ἀνέχω","o":14,"ar":"<f><o>ἀν-έχω</o>،</f> <s><b>يرفع (يُمسك إلى فوق)</b>؛ وفي العهد الجديد دائمًا في الصيغة الوسطى، <b>يحتمل</b>، <b>يصبر على</b>: في العهد الجديد مع المضاف إليه للشخص، <r v=\"Matt.17.17\"></r>، <r v=\"Mark.9.19\"></r>، <r v=\"Luke.9.41\"></r>، <r v=\"2Cor.11.1\"></r>، <r v=\"2Cor.11.19\"></r>، <r v=\"Eph.4.2\"></r>، <r v=\"Col.3.13\"></r>؛ يليه <g>μικρόν τι</g>، مع المضاف إليه للشخص ومع المضاف إليه للشيء، <r v=\"2Cor.11.1\"></r>؛ مع القابل للشيء، <r v=\"2Thess.1.4\"></r>؛ يليه <g>εἴ τις</g>، <r v=\"2Cor.11.20\"></r>؛ مطلقًا (بلا مفعول)، <r v=\"1Cor.4.12\"></r>، <r v=\"2Cor.11.4\"></r>؛ <b>يحتمل</b> = <b>يُصغي إلى</b>، مع المضاف إليه للشخص، <r v=\"Acts.18.14\"></r>؛ مع المضاف إليه للشيء، <r v=\"2Tim.4.3\"></r>، <r v=\"Heb.13.22\"></r> .†</s>","en":"<f><o>ἀν-έχω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H662\">אפק</h> hithp.;]</e> </et> <s><b>to hold up</b>; in NT always mid., <b>to bear with</b>, <b>endure</b>: in cl. most freq. c. acc., but in NT c. gen. pers., <r v=\"Matt.17.17\"></r>, <r v=\"Mark.9.19\"></r>, <r v=\"Luke.9.41\"></r>, <r v=\"2Cor.11.1\"></r>, <r v=\"2Cor.11.19\"></r>, <r v=\"Eph.4.2\"></r>, <r v=\"Col.3.13\"></r>; seq. <g>μικρόν τι</g>, c. gen. pers. and c. gen. rei, <r v=\"2Cor.11.1\"></r>; c. dat. rei, <r v=\"2Thess.1.4\"></r> (v M, <i>Th.</i>, in l.); seq. <g>εἴ τις</g>, <r v=\"2Cor.11.20\"></r>; absol., <r v=\"1Cor.4.12\"></r>, <r v=\"2Cor.11.4\"></r>; <b>to bear with</b> = <b>to listen to</b>, c. gen. pers., <r v=\"Acts.18.14\"></r>; c. gen. rei, <r v=\"2Tim.4.3\"></r>, <r v=\"Heb.13.22\"></r> (cf. <x><g>προσανέχω</g></x> and MM, <i>VGT</i>, s.v.).†</s>"},"G436":{"l":"ἀνθίστημι","o":14,"ar":"<f><o>ἀνθ-ίστημι</o></f> <s n=\"1.\">في المضارع والماضي الناقص والمستقبل والماضي البسيط الأول المبني للمعلوم، سببي، <b>يُقيم ضد</b>.</s> <s n=\"2.\">في الصيغة الوسطى والمبني للمجهول، وأيضًا في التام والماضي البسيط الثاني المبني للمعلوم، <b>يقاوم</b>، <b>يصمد أمام</b>، <b>يعارض</b>: مع القابل، <r v=\"Matt.5.39\"></r>، <r v=\"Luke.21.15\"></r>، <r v=\"Acts.6.10\"></r> <r v=\"Acts.13.8\"></r>، <r v=\"Rom.9.19\"></r> <r v=\"Rom.13.2\"></r>، <r v=\"Gal.2.11\"></r>، <r v=\"Eph.6.13\"></r>، <r v=\"2Tim.3.8\"></r> <r v=\"2Tim.4.15\"></r>، <r v=\"Jas.4.7\"></r>، <r v=\"1Pet.5.9\"></r>.†</s>","en":"<f><o>ἀνθ-ίστημι</o></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ἵστημι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5975\">עמד</h>, <h n=\"H3320\">יצב</h>, etc.;]</e> </et> <s n=\"1.\">in pres., impf., fut. and 1 aor. act., causal, <b>to set against</b>.</s> <s n=\"2.\">In mid. and pass., also pf. and 2 aor. act., <b>to withstand</b>, <b>resist</b>, <b>oppose</b>: c. dat., <r v=\"Matt.5.39\"></r>, <r v=\"Luke.21.15\"></r>, <r v=\"Acts.6.10\"></r> <r v=\"Acts.13.8\"></r>, <r v=\"Rom.9.19\"></r> <r v=\"Rom.13.2\"></r>, <r v=\"Gal.2.11\"></r>, <r v=\"Eph.6.13\"></r>, <r v=\"2Tim.3.8\"></r> <r v=\"2Tim.4.15\"></r>, <r v=\"Jas.4.7\"></r>, <r v=\"1Pet.5.9\"></r>.†</s>"},"G457":{"l":"ἄνοιξις","o":1,"ar":"<f>* <o>ἄνοιξις</o>، <g>-εως, ἡ</g></f> <s><b>فتح</b> (في اليونانية الحديثة، <i>الربيع</i>): <g>ἐν ἀ.</g>، <b>كلما فتحتُ</b>، <r v=\"Eph.6.19\"></r>.†</s>","en":"<f>* <o>ἄνοιξις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνοίγω</g></x>),</e> </et> <s><b>an opening</b> (in MGr., <i>springtime</i>): <g>ἐν ἀ.</g>, <b>as often as I open</b>, <r v=\"Eph.6.19\"></r>.†</s>"},"G489":{"l":"ἀντιμισθία","o":2,"ar":"<f>*† <o>ἀντιμισθία</o>، <g>-ας, ἡ</g></f> <s><b>جزاء</b>، <b>مكافأة، مقابل</b>: بالمعنى الحسن، <r v=\"2Cor.6.13\"></r>؛ بالمعنى السيئ، <r v=\"Rom.1.27\"></r>.†</s>","en":"<f>*† <o>ἀντιμισθία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀντίμισθος</g></x>, <i>for a reward</i>),</e> </et> <s><b>a reward</b>, <b>requital</b>: in good sense, <r v=\"2Cor.6.13\"></r>; in bad sense, <r v=\"Rom.1.27\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G470":{"l":"ἀνταποκρίνομαι","o":2,"ar":"<f>† <o>ἀντ-απο-κρίνομαι</o></f> <s><b>يجيب بالمقابل</b>، <b>يردّ معترضًا</b>: يليه <g>πρός</g>، مع المنصوب للأشياء، <r v=\"Luke.14.6\"></r>؛ مع القابل للأشخاص، <r v=\"Rom.9.20\"></r>.†</s>","en":"<f>† <o>ἀντ-απο-κρίνομαι</o></f> <et> <e t=\"derivation\">(<g>ἀντί</g>, <g>ἀποκρίνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.5.29\"></r>, <r v=\"Job.16.9\"></r> (<r v=\"Job.16.8\"></r>) <r v=\"Job.32.12\"></r> (<h n=\"H6030\">ענה</h>)*;]</e> </et> <s><b>to answer again</b>, <b>reply against</b>: seq. <g>πρός</g>, c. acc. rei, <r v=\"Luke.14.6\"></r>; c. dat. pers., <r v=\"Rom.9.20\"></r>.†</s>"},"G472":{"l":"ἀντέχω","o":4,"ar":"<f><o>ἀντ-έχω</o></f> <s n=\"1.\">متعدٍّ: <b>يمسك قبالة</b>.</s> <s n=\"2.\">لازم: <b>يصمد، يقاوم</b>. الصيغة الوسطى: 1. في اليونانية الكلاسيكية: <b>يصمد أمام</b>.</s> <s n=\"3.\"><b>يتمسك بـ</b>، <b>يلازم</b>: مع المضاف إليه، <r v=\"Matt.6.24\"></r>، <r v=\"Luke.16.13\"></r>، <r v=\"1Thess.5.14\"></r>، <r v=\"Titus.1.9\"></r>.†</s>","en":"<f><o>ἀντ-έχω</o></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ἔχω</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2388\">חָזַק</h> hi., etc.;]</e> </et> <s n=\"1.\">trans., <b>to hold against</b>.</s> <s n=\"2.\">Intrans., <b>to withstand</b>. Mid. 1. in cl., <b>to hold out against</b>.</s> <s n=\"3.\">(cf. MM, <i>VGT</i>, s.v.), <b>to hold firmly to</b>, <b>cleave to</b>: c. gen. (v. Bl., § 36, 2), <r v=\"Matt.6.24\"></r>, <r v=\"Luke.16.13\"></r>, <r v=\"1Thess.5.14\"></r> (v. M, <i>Th.</i>, in l.), <r v=\"Titus.1.9\"></r>.†</s>"},"G423":{"l":"ἀνεπίλημπτος","o":3,"ar":"<f>* <o>ἀν-επί-λημπτος</o>، <g>-ον</g></f> <s><b>بلا لوم</b>: <r v=\"1Tim.3.2\"></r>، <r v=\"1Tim.5.7\"></r>، <r v=\"1Tim.6.14\"></r>.†</s>","en":"<f>* <o>ἀν-επί-λημπτος</o> (Rec. <g>-λμπτος</g>; Bl., § 6, 8), <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g>, <x><g>ἐπιλαμβάνω</g></x>),</e> </et> <s><b>without reproach</b>: <r v=\"1Tim.3.2\"></r> <r v=\"1Tim.5.7\"></r> <r v=\"1Tim.6.14\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἄμεμπτος</g></x>, <x><g>ἀνέγκλητος</g></x>. It is stronger than these, for it implies not only that the man is of good report, but that he is deservedly so (cf. MM, <i>VGT</i>, s.v.).</sy>"},"G497":{"l":"ἀντιστρατεύομαι","o":1,"ar":"<f>* <o>ἀντι-στρατεύομαι</o>،</f> <s><b>يحارب ضدّ</b>: مع القابل، <r v=\"Rom.7.23\"></r>.†</s>","en":"<f>* <o>ἀντι-στρατεύομαι</o>,</f> <s><b>to make war against</b>: c. dat., <r v=\"Rom.7.23\"></r>.†</s>"},"G407":{"l":"ἀνδρίζω","o":1,"ar":"<f><o>ἀνδρίζω</o>،</f> <s><b>يجعله رجلاً</b>. الصيغة الوسطى: <b>يتصرّف كرجل، يتشدّد</b>: <r v=\"1Cor.16.13\"></r>.†</s>","en":"<f><o>ἀνδρίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2388\">חזק</h>, <h n=\"H553\">אמץ</h> (<r v=\"Josh.1.6\"></r> ff., <r v=\"1Chr.22.19\"></r>, al.; in <r v=\"2Sam.10.12\"></r>, <r v=\"Ps.27.14\"></r> <r v=\"Ps.31.25\"></r> combined with <x><g>κρατιοῦσθαι</g></x>, as in <r v=\"1Cor.16.13\"></r>);]</e> </et> <s><b>to make a man of</b>. Mid., <b>to play the man</b> (cf. MM, <i>VGT</i>, s.v.): <r v=\"1Cor.16.13\"></r>.†</s>"},"G434":{"l":"ἀνήμερος","o":1,"ar":"<f>* <o>ἀν-ήμερος</o>، <g>-ον</g></f> <s><b>غير مُروَّض</b>، <b>شرس</b>: <r v=\"2Tim.3.3\"></r>.†</s>","en":"<f>* <o>ἀν-ήμερος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>ἀ-</g>, <x><g>ἥμερο</g></x>),</e> </et> <s><b>not tame</b>, <b>savage</b> (MM, <i>VGT</i>, s.v.): <r v=\"2Tim.3.3\"></r>.†</s>"},"G419":{"l":"ἀνεξεραύνητος","o":1,"ar":"<f>** <o>ἀνεξεραύνητος</o></f> <s><b>لا يُفحَص، لا يُستقصى</b>: <r v=\"Rom.11.33\"></r>.†</s>","en":"<f>** <o>ἀνεξεραύνητος</o></f> <et> <e t=\"derivation\">(Rec. <g>-εύνητος</g>, as in Attic; M, <i>Pr.</i>, 46), <g>-ον</g> (&lt; <x><g>ἐξ-ερευνάω</g></x>),</e> <e t=\"septuagint\">[in Sm. (<g>-ευ-</g>): <r v=\"Prov.25.3\"></r>*;]</e> </et> <s><b>unsearchable</b>: <r v=\"Rom.11.33\"></r>.†</s>"},"G490":{"l":"Ἀντιόχεια","o":18,"ar":"<f><o>Ἀντιόχεια</o>، <g>-ας, ἡ</g>،</f> <s><b>أنطاكية</b>؛ <s n=\"1.\">في سورية: <r v=\"Acts.11.19\"></r>، <r v=\"Acts.11.20\"></r>، <r v=\"Acts.11.22\"></r>، <r v=\"Acts.11.26\"></r>، <r v=\"Acts.11.27\"></r>، <r v=\"Acts.13.1\"></r>، <r v=\"Acts.14.26\"></r>، <r v=\"Acts.15.22\"></r>، <r v=\"Acts.15.23\"></r>، <r v=\"Acts.15.30\"></r>، <r v=\"Acts.15.35\"></r>، <r v=\"Acts.18.22\"></r>، <r v=\"Gal.2.11\"></r>.</s> <s n=\"2.\">في بيسيدية: <r v=\"Acts.13.14\"></r>، <r v=\"Acts.14.19\"></r>، <r v=\"Acts.14.21\"></r>، <r v=\"2Tim.3.11\"></r>.†</s> </s>","en":"<f><o>Ἀντιόχεια</o>, <g>-ας, ἡ</g>,</f> <s><b>Antioch</b>; <s n=\"1.\">in Syria: <r v=\"Acts.11.19\"></r>, <r v=\"Acts.11.20\"></r>, <r v=\"Acts.11.22\"></r>, <r v=\"Acts.11.26\"></r>, <r v=\"Acts.11.27\"></r> <r v=\"Acts.13.1\"></r> <r v=\"Acts.14.26\"></r> <r v=\"Acts.15.22\"></r>, <r v=\"Acts.15.23\"></r>, <r v=\"Acts.15.30\"></r>, <r v=\"Acts.15.35\"></r> <r v=\"Acts.18.22\"></r>, <r v=\"Gal.2.11\"></r>.</s> <s n=\"2.\">In Pisidia: <r v=\"Acts.13.14\"></r> <r v=\"Acts.14.19\"></r>, <r v=\"Acts.14.21\"></r>, <r v=\"2Tim.3.11\"></r>.†</s> </s>"},"G440":{"l":"ἄνθραξ","o":1,"ar":"<f><o>ἄνθραξ</o>، <g>-ακος, ὁ</g>،</f> <s><b>جمر</b>، <b>فحم</b>: <g>ἄ. πυρός</g>: <b>جمر نار (جمرة متّقدة)</b>: <r v=\"Rom.12.20\"></r>.†</s>","en":"<f><o>ἄνθραξ</o>, <g>-ακος, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1513\">גַּחֶלֶת</h>;]</e> </et> <s><b>coal</b>, <b>charcoal</b>: . <g>ἄ. πυρός</g>, <b>a burning coal</b>, <r v=\"Rom.12.20\"></r>.†</s>"},"G469":{"l":"ἀνταπόδοσις","o":1,"ar":"<f><o>ἀντ-από-δοσις</o>، <g>-εως, ἡ</g></f> <s><b>مجازاة</b>: <r v=\"Col.3.24\"></r>.†</s>","en":"<f><o>ἀντ-από-δοσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(v. supr.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1576\">גְּמוּל</h>, <h n=\"H7966\">שִׁלּוּם</h>;]</e> </et> <s><b>recompense</b>: <r v=\"Col.3.24\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G463":{"l":"ἀνοχή","o":2,"ar":"<f>** <o>ἀνοχή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>إمساك</b>، <b>إمهال</b>. </s> <s n=\"2.\"><b>إمهال</b>، تأجيل العقاب: <r v=\"Rom.2.4\"></r>، <r v=\"Rom.3.26\"></r>.†</s>","en":"<f>** <o>ἀνοχή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνέχω</g></x>, <g>-ομαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.12.25\"></r> (RV, <i>respite</i>)*;]</e> </et> <s n=\"1.\">in cl., <b>a holding back</b>, <b>delaying</b> (MM, <i>VGT</i>, s.v.). </s> <s n=\"2.\"><b>forbearance</b>, delay of punishment: <r v=\"Rom.2.4\"></r> <r v=\"Rom.3.26\"></r>.†</s> <sy><i>SYN.</i>: <x><g>μακροθυμία</g></x>, <x><g>ὑπομονή</g></x>. <g>ἀ.</g>, <b>forbearance</b>, is the result and expression of <g>μ.</g>, which involves the idea of tolerance, <i>long-suffering</i>, as God with sinners. <g>ὑ.</g> expresses patience with respect to things, as <g>μ.</g> with persons; it is active as well as passive, denotes not merely <i>endurance</i> but perseverance (v. Tr., <i>Syn.</i>, § liii; Lft., <i>Notes</i>, 259, 273; <i>DB</i>, ii, 47).</sy>"},"G424":{"l":"ἀνέρχομαι","o":5,"ar":"<f><o>ἀν-έρχομαι</o>،</f> <s><b>صعد</b>: <r v=\"John.6.3\"></r>، <r v=\"Gal.1.17\"></r>، <r v=\"Gal.1.18\"></r> (قارن <g>ἐπανέρχ-</g>).†</s>","en":"<f><o>ἀν-έρχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.13.12\"></r> (<h n=\"H1980\">הָלַךְ</h>)*;]</e> </et> <s><b>to go up</b>: <r v=\"John.6.3\"></r>, <r v=\"Gal.1.17\"></r>, <r v=\"Gal.1.18\"></r> (cf. <g>ἐπανέρχ-</g>; and on its use of \"going up\" to the capital, MM, <i>VGT</i>, s.v.).†</s>"},"G422":{"l":"ἀνεπαίσχυντος","o":1,"ar":"<f>*† <o>ἀν-επ-αίσχυντος</o>، <g>-ον</g></f> <s><b>لا يُخزى</b>: <r v=\"2Tim.2.15\"></r>.†</s>","en":"<f>*† <o>ἀν-επ-αίσχυντος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἐπαισχύνομαι</g></x>),</e> </et> <s><b>not to be put to shame</b>: <r v=\"2Tim.2.15\"></r>.†</s>"},"G458":{"l":"ἀνομία","o":15,"ar":"<f><o>ἀνομία</o>، <g>-ας, ἡ</g></f> <s><b>تعدٍّ على الناموس، انعدام الشريعة</b>، <b>إثم</b>: <r v=\"Matt.7.23\"></r> <r v=\"Matt.13.41\"></r> <r v=\"Matt.23.28\"></r> <r v=\"Matt.24.12\"></r>، <r v=\"Rom.6.19\"></r>، <r v=\"2Cor.6.14\"></r>، <r v=\"2Thess.2.3\"></r>، <r v=\"2Thess.2.7\"></r>، <r v=\"Titus.2.14\"></r>، <r v=\"Heb.1.9\"></r>، <r v=\"1John.3.4\"></r>؛ في الجمع (كما في السبعينية، <r v=\"Ps.31.1\"></r>، وفي مواضع أخرى)، عن أعمال التعدي أو مظاهره: <r v=\"Rom.4.7\"></r><i>(السبعينية)</i>، <r v=\"Heb.10.17\"></r>.†</s>","en":"<f><o>ἀνομία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄνομος</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5771\">עָוֺן</h>, <h n=\"H6588\">פֶּשַׁע</h>, <h n=\"H8441\">תּוֹעֵבָה</h>, <h n=\"H7562\">רֶשַׁע</h>, etc.;]</e> </et> <s><b>lawlessness</b>, <b>iniquity</b>: <r v=\"Matt.7.23\"></r> <r v=\"Matt.13.41\"></r> <r v=\"Matt.23.28\"></r> <r v=\"Matt.24.12\"></r>, <r v=\"Rom.6.19\"></r>, <r v=\"2Cor.6.14\"></r>, <r v=\"2Thess.2.3\"></r>, <r v=\"2Thess.2.7\"></r>, <r v=\"Titus.2.14\"></r>, <r v=\"Heb.1.9\"></r>, <r v=\"1John.3.4\"></r>; in pl. (as LXX, <r v=\"Ps.31.1\"></r>, al.; v. Bl., § 32, 6; Swete, <i>Mk.</i>, 153), of acts or manifestations of lawlessness: <r v=\"Rom.4.7\"></r><i>(LXX)</i>, <r v=\"Heb.10.17\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>ἁμάρτημα</g></x>, <x><g>ἄνομος</g></x>.</sy>"},"G498":{"l":"ἀντιτάσσω","o":5,"ar":"<f><o>ἀντι-τάσσω</o> (في الأتيكية <g>-ττω</g>)،</f> <s><b>اصطفّ للقتال ضد</b>؛ الصيغة الوسطى: <b>وقف ضد</b>، <b>قاوم</b>: مطلقًا، <r v=\"Acts.18.6\"></r>؛ مع القابل، <r v=\"Rom.13.2\"></r>، <r v=\"Jas.4.6\"></r> <r v=\"Jas.5.6\"></r>، <r v=\"1Pet.5.5\"></r>.†</s>","en":"<f><o>ἀντι-τάσσω</o> (Att., <g>-ττω</g>),</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3887\">לוּץ</h> hi., <h n=\"H5375\">נשׂא</h>, etc.;]</e> </et> <s><b>to range on battle against</b>; mid., <b>to set oneself against</b>, <b>resist</b>: absol., <r v=\"Acts.18.6\"></r>; c. dat., <r v=\"Rom.13.2\"></r>, <r v=\"Jas.4.6\"></r> <r v=\"Jas.5.6\"></r>, <r v=\"1Pet.5.5\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G415":{"l":"ἀνελεήμων","o":1,"ar":"<f><o>ἀν-ελεήμων</o>، <g>-ον</g></f> <s><b>بلا رحمة</b>: <r v=\"Rom.1.13\"></r>.†</s>","en":"<f><o>ἀν-ελεήμων</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>-ἀ</g>, <x><g>ἐλεήμων</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H393\">אַכְזָר</h>;]</e> </et> <s><b>without mercy</b>: <r v=\"Rom.1.13\"></r>.†</s>"},"G459":{"l":"ἄνομος","o":9,"ar":"<f><o>ἄ-νομος</o>، <g>-ον</g></f> <s n=\"1.\"><b>أثيم (مخالف للناموس)</b>، <b>شرير</b>: <r v=\"Mark.15.28\"></r>، <r v=\"Luke.22.37\"></r>، <r v=\"Acts.2.23\"></r>، <r v=\"1Tim.1.9\"></r>، <r v=\"2Pet.2.8\"></r>؛ <g>ὁ ἄ.</g>، <r v=\"2Thess.2.8\"></r> (= <g>ὁ ἄνθρωπος τῆς ἀνομίας</g>، <r v=\"2Thess.2.3\"></r>).</s> <s n=\"2.\"><b>بلا ناموس</b> (= <g>οἱ μὴ ὑπὸ νόμον</g>، <r v=\"Rom.2.14\"></r>): <r v=\"1Cor.9.21\"></r>.†</s>","en":"<f><o>ἄ-νομος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>ἀ.</g> neg., <x><g>νόμος</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5771\">עָוֺן</h>, <h n=\"H6586\">פֶּשַׁע</h>, <h n=\"H7562\">רֶשַׁע</h>, etc.;]</e> </et> <s n=\"1.\"><b>lawless</b>, <b>wicked</b>: <r v=\"Mark.15.28\"></r>, <r v=\"Luke.22.37\"></r>, <r v=\"Acts.2.23\"></r>, <r v=\"1Tim.1.9\"></r>, <r v=\"2Pet.2.8\"></r>; <g>ὁ ἄ.</g>, <r v=\"2Thess.2.8\"></r> (= <g>ὁ ἄνθρωπος τῆς ἀνομίας</g>, <r v=\"2Thess.2.3\"></r>).</s> <s n=\"2.\"><b>without law</b> (= <g>οἱ μὴ ὑπὸ νόμον</g>, <r v=\"Rom.2.14\"></r>): <r v=\"1Cor.9.21\"></r> (MM, <i>VGT</i>, s.v.).†</s> <sy><i>SYN.</i>: v.s. <x><g>ἄθεσμος</g></x>.</sy>"},"G480":{"l":"ἀντίκειμαι","o":8,"ar":"<f><o>ἀντί-κειμαι</o>،</f> <s n=\"1.\"><b>كان مقابلاً لـ</b>.</s> <s n=\"2.\"><b>قاوم</b>، <b>ضادّ</b>، <b>عاند</b>: مع القابل، <r v=\"Luke.13.17\"></r> <r v=\"Luke.21.15\"></r>، <r v=\"Gal.5.17\"></r>، <r v=\"1Tim.1.10\"></r>؛ اسم الفاعل بمعنى الاسم (<g>ὁ</g>) <g>ἀντικείμενος</g>، <r v=\"1Cor.16.9\"></r>، <r v=\"Phil.1.28\"></r>، <r v=\"2Thess.2.4\"></r>، <r v=\"1Tim.5.14\"></r>.†</s>","en":"<f><o>ἀντί-κειμαι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H340\">איב</h>, <h n=\"H6696\">צוּר</h>, <h n=\"H7853\">שׂטן</h>, etc.;]</e> </et> <s n=\"1.\"><b>to lie opposite to</b>.</s> <s n=\"2.\"><b>to oppose</b>, <b>withstand</b>, <b>resist</b>: c. dat., <r v=\"Luke.13.17\"></r> <r v=\"Luke.21.15\"></r>, <r v=\"Gal.5.17\"></r>, <r v=\"1Tim.1.10\"></r>; as participial subst. (<g>ὁ</g>) <g>ἀντικείμενος</g>, <r v=\"1Cor.16.9\"></r>, <r v=\"Phil.1.28\"></r>, <r v=\"2Thess.2.4\"></r>, <r v=\"1Tim.5.14\"></r> (Cremer, 746).†</s>"},"G475":{"l":"ἀντιδιατίθημι","o":1,"ar":"<f>*† <o>ἀντι-δια-τίθημι</o>،</f> <s>في الصيغة الوسطى، <b>وقف موقف المعارضة</b>، <b>قاوم</b>: <r v=\"2Tim.2.25\"></r>.</s>","en":"<f>*† <o>ἀντι-δια-τίθημι</o>,</f> <s>in mid, <b>to place oneself in opposition</b>, <b>oppose</b>: <r v=\"2Tim.2.25\"></r> (EV; but v. Field, <i>Notes</i>, 215 f.; cf. MM, <i>VGT</i>, s.v.).</s>"},"G467":{"l":"ἀνταποδίδωμι","o":7,"ar":"<f><o>ἀντ-απο-δίδωμι</o></f> <s><b>يردّ مقابلاً مكافئًا</b>، <b>يُجازي</b>، <b>يكافئ</b> (و<g>ἀντί</g> تفيد معنى الردّ الكامل التام)؛ <s n=\"(a)\">بالمعنى الحسن: <r v=\"Luke.14.14\"></r>، <r v=\"Rom.11.35\"></r>، <r v=\"1Thess.3.9\"></r>؛</s> <s n=\"(b)\">بالمعنى السيئ: <r v=\"Rom.12.19\"></r>، <r v=\"2Thess.1.6\"></r>، <r v=\"Heb.10.30\"></r>.†</s> </s>","en":"<f><o>ἀντ-απο-δίδωμι</o></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ἀποδίδωμι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7999\">שׁלם</h> pi., <h n=\"H1580\">גּמל</h>, <h n=\"H7725\">שׁוּב</h> hi., etc.;]</e> </et> <s><b>to give back as an equivalent</b>, <b>recompense</b>, <b>requital</b> (the <g>ἀντί</g> expressing the idea of full, complete return; v. Lft., <i>Notes</i>, 46); <s n=\"(a)\">in favourable sense: <r v=\"Luke.14.14\"></r>, <r v=\"Rom.11.35\"></r>, <r v=\"1Thess.3.9\"></r>;</s> <s n=\"(b)\">in unfavourable sense: <r v=\"Rom.12.19\"></r>, <r v=\"2Thess.1.6\"></r>, <r v=\"Heb.10.30\"></r>.†</s> </s>"},"G425":{"l":"ἄνεσις","o":5,"ar":"<f><o>ἄνεσις</o>، <g>-εως, ἡ</g>،</f> <s><b>إرخاء، تخفيف، راحة</b>: <r v=\"Acts.24.23\"></r> (أي <i>تساهل، تسهيل</i>)؛ وعند بولس الرسول عكس <x><g>θλίψις</g></x>، مذكورًا أو مفهومًا: <b>راحة، فَرَج</b>: <r v=\"2Cor.2.12\"></r> <r v=\"2Cor.7.5\"></r> <r v=\"2Cor.8.13\"></r>، <r v=\"2Thess.1.7\"></r>.†</s>","en":"<f><o>ἄνεσις</o>, <g>-εως, ἡ</g>,</f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνίημι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Esd.4.22\"></r> (<h n=\"H7960\">שָׁלוּ</h>), <r v=\"2Chr.23.15\"></r>, <r v=\"1Esd.4.62\"></r>, <r v=\"Wis.13.13\"></r>, <r v=\"Sir.15.20\"></r> <r v=\"Sir.26.10\"></r>*;]</e> </et> <s><b>a loosening, relaxation</b>: <r v=\"Acts.24.23\"></r> (RV, <i>indulgence</i>; cf. MM, <i>VGT</i>, s.v.); by St. Paul, opp. to <x><g>θλίψις</g></x>, expressed or understood, <b>relief</b>: <r v=\"2Cor.2.12\"></r> <r v=\"2Cor.7.5\"></r> <r v=\"2Cor.8.13\"></r>, <r v=\"2Thess.1.7\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἀνάπαυσις</g></x> (q.v.).†</sy>"},"G462":{"l":"ἀνόσιος","o":2,"ar":"<f><o>ἀν-όσιος</o>، <g>-ον</g></f> <s><b>غير طاهر، نجس</b>، <b>دنس</b>: <r v=\"1Tim.1.9\"></r>، <r v=\"2Tim.3.2\"></r>.†</s>","en":"<f><o>ἀν-όσιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>ἀ-</g> neg., <x><g>ὅσιος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.22.9\"></r> (<h n=\"H2154\">זִמָּה</h>, <r v=\"Wis.12.4\"></r>, <r v=\"2Macc.7.34\"></r> <r v=\"2Macc.8.32\"></r>, <r v=\"3Macc.2.2\"></r> <r v=\"3Macc.5.7\"></r>, <r v=\"4Macc.12.11\"></r>*;]</e> </et> <s><b>unholy</b>, <b>profane</b> (Cremer, 464): <r v=\"1Tim.1.9\"></r>, <r v=\"2Tim.3.2\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G466":{"l":"ἀνταναπληρόω","o":1,"ar":"<f>* <o>ἀντ-ανα-πληρόω</o>، <g>-ῶ</g></f> <s><b>يُكمل بدوره، يملأ ما ينقص (عوضًا)</b>: <r v=\"Col.1.24\"></r>.†</s>","en":"<f>* <o>ἀντ-ανα-πληρόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ἀναπληρόω</g></x>),</e> </et> <s><b>to fill up in turn</b>: <r v=\"Col.1.24\"></r> (v. Lft., in l.; MM, <i>VGT</i>, s.v.).†</s>"},"G431":{"l":"ἀνεψιός","o":1,"ar":"<f><o>ἀνεψιός</o>، <g>-οῦ, ὁ</g></f> <s><b>ابن عمّ، ابن خال</b>: <r v=\"Col.4.10\"></r>.†</s>","en":"<f><o>ἀνεψιός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(cf. Lat. <l>nepos</l>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.36.11\"></r> (<h n=\"H1730\">דּוֹד</h> <h n=\"H1121\">בֶּן</h>), <r v=\"Tob.7.2\"></r> <r v=\"Tob.9.6\"></r> <h>א</h>*;]</e> </et> <s><b>a cousin</b>: <r v=\"Col.4.10\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G468":{"l":"ἀνταπόδομα","o":2,"ar":"<f>† <o>ἀντ-από-δομα</o>، <g>-τος, τό</g></f> <s><b>مجازاة</b>؛ <s n=\"(a)\">بالمعنى الحسن: <r v=\"Luke.14.12\"></r>؛</s> <s n=\"(b)\">بالمعنى السيئ: <r v=\"Rom.11.9\"></r>.†</s> </s>","en":"<f>† <o>ἀντ-από-δομα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνταποδίδωμι</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1576\">גְּמוּל</h>;]</e> <e t=\"derivation\">( = cl. <g>-δοσις</g>, q.v.),</e> </et> <s><b>requital</b>; <s n=\"(a)\">in favourable sense: <r v=\"Luke.14.12\"></r>;</s> <s n=\"(b)\">in unfavourable sense: <r v=\"Rom.11.9\"></r>.†</s> </s>"},"G420":{"l":"ἀνεξίκακος","o":1,"ar":"<f>*† <o>ἀνεξί-κακος</o>، <g>-ον</g></f> <s><b>صبور على المشقات</b> (قارن <x><g>ἀνεξικακία</g></x>، <r v=\"Wis.2.19\"></r>): <r v=\"2Tim.2.24\"></r>.†</s>","en":"<f>*† <o>ἀνεξί-κακος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; fut., <x><g>ἀνέξομαι</g></x>, <x><g>κακός</g></x>),</e> </et> <s><b>patiently forbearing</b> (cf. <x><g>ἀνεξικακία</g></x>, <r v=\"Wis.2.19\"></r>; and v. MM, <i>VGT</i>, s.v.): <r v=\"2Tim.2.24\"></r>.†</s>"},"G405":{"l":"ἀνδραποδιστής","o":1,"ar":"<f>* <o>ἀνδραποδιστής</o>، <g>-οῦ, ὁ</g></f> <s><b>تاجر عبيد</b>، <b>سارق الناس</b>: <r v=\"1Tim.1.10\"></r>.†</s>","en":"<f>* <o>ἀνδραποδιστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνδράποδον</g></x>, <i>a slave</i>, captured in war),</e> </et> <s><b>a slave-dealer</b>, <b>kidnapper</b>: <r v=\"1Tim.1.10\"></r> (v. MM, <i>VGT</i>, s.v.).†</s>"},"G410":{"l":"ἀνέγκλητος","o":5,"ar":"<f>** <o>ἀν-έγκλητος</o>، <g>-ον</g></f> <s><b>لا يُشكى عليه</b>، <b>بلا لوم</b>: <r v=\"1Cor.1.8\"></r>، <r v=\"Col.1.22\"></r>، <r v=\"1Tim.3.10\"></r>، <r v=\"Titus.1.6\"></r>، <r v=\"Titus.1.7\"></r>.†</s>","en":"<f>** <o>ἀν-έγκλητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g>, <x><g>ἐγκαλέω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.5.31\"></r>*;]</e> </et> <s><b>not to be called to account</b>, <b>unreprovable</b>: <r v=\"1Cor.1.8\"></r>, <r v=\"Col.1.22\"></r>, <r v=\"1Tim.3.10\"></r>, <r v=\"Titus.1.6\"></r>, <r v=\"Titus.1.7\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἄμεμπτος</g></x>, <x><g>ὀνεπίλημπτος</g></x> (v. Tr., <i>Syn.</i>, § ciii; Cremer, 742; MM, <i>VGT</i>, s.v.).</sy>"},"G454":{"l":"ἄνοια","o":2,"ar":"<f><o>ἄνοια</o>، <g>-ας, ἡ</g></f> <s><b>حماقة</b>، <b>جهل</b>: <r v=\"2Tim.3.9\"></r>؛ وهي التي تظهر في الغضب العنيف (<b>حُمق</b>): <r v=\"Luke.6.11\"></r>.†</s>","en":"<f><o>ἄνοια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄ-νοος</g></x>, <i>without understanding</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.14.8\"></r> <r v=\"Prov.22.15\"></r> (<h n=\"H200\">אִוֶּלֶת</h>), <r v=\"Wis.15.18\"></r>, al.;]</e> </et> <s><b>folly</b>, <b>foolishness</b>: <r v=\"2Tim.3.9\"></r>; expressed in violent rage (cf. Plat., <i>Tim.</i>, 86B): <r v=\"Luke.6.11\"></r>.†</s>"},"G411":{"l":"ἀνεκδιήγητος","o":1,"ar":"<f>*† <o>ἀν-εκδιήγητος</o>، <g>-ον</g></f> <s><b>لا يُعبَّر عنه</b>: <r v=\"2Cor.9.15\"></r>.†</s>","en":"<f>*† <o>ἀν-εκδιήγητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g>, <x><g>ἐκδιηγέομαι</g></x>),</e> </et> <s><b>inexpressible</b>: <r v=\"2Cor.9.15\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G477":{"l":"ἀντίθεσις","o":1,"ar":"<f>* <o>ἀντί-θεσις</o>، <g>-εως, ἡ</g></f> <s><b>معارضة، مخالفة</b>: <r v=\"1Tim.6.20\"></r>.†</s>","en":"<f>* <o>ἀντί-θεσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>τίθημι</g></x>),</e> </et> <s><b>opposition</b>: <r v=\"1Tim.6.20\"></r>.†</s>"},"G408":{"l":"Ἀνδρόνικος","o":1,"ar":"<f><o>Ἀνδρόνικος</o>، <g>-ου, ὁ</g>،</f> <s><b>أندرونكوس</b>: <r v=\"Rom.16.7\"></r>.†</s>","en":"<f><o>Ἀνδρόνικος</o>, <g>-ου, ὁ</g>,</f> <s><b>Andronicus</b>: <r v=\"Rom.16.7\"></r>.†</s>"},"G453":{"l":"ἀνόητος","o":6,"ar":"<f><o>ἀ-νόητος</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>غير مفكَّر فيه</b>، <b>غير مفهوم</b>.</s> <s n=\"2.\"><b>غير فاهم</b>، <b>غبي</b>: <r v=\"Luke.24.25\"></r>، <r v=\"Rom.1.14\"></r>، <r v=\"Gal.3.1\"></r>، <r v=\"Gal.3.3\"></r>، <r v=\"1Tim.6.9\"></r>، <r v=\"Titus.3.3\"></r>.†</s>","en":"<f><o>ἀ-νόητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>ἀ-</g> neg., <x><g>νοητός</g></x>; &lt; <x><g>νοέω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.17.28\"></r> (<h n=\"H191\">אֱוִיל</h>), <r v=\"Sir.42.8\"></r>, al.;]</e> </et> <s n=\"1.\"><b>not thought on</b>, <b>not understood</b> (Hom., Plat.).</s> <s n=\"2.\"><b>not understanding</b>, <b>foolish</b> (Hdt., al., LXX): <r v=\"Luke.24.25\"></r>, <r v=\"Rom.1.14\"></r>, <r v=\"Gal.3.1\"></r>, <r v=\"Gal.3.3\"></r>, <r v=\"1Tim.6.9\"></r>, <r v=\"Titus.3.3\"></r> (Cremer, 438, 790; MM, <i>VGT</i>, s.v.).†</s> <sy><i>SYN.</i>: <x><g>ἀσύνετος</g></x> (v. Tr., <i>Syn.</i>, § lxxv).</sy>"},"G409":{"l":"ἀνδροφόνος","o":1,"ar":"<f>** <o>ἀνδρο-φόνος</o>، <g>-ου, ὁ</g>،</f> <s><b>قاتل الناس</b>: <r v=\"1Tim.1.9\"></r> (قارن <x><g>φονεύς</g></x>).†</s>","en":"<f>** <o>ἀνδρο-φόνος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.9.28\"></r>*;]</e> </et> <s><b>a man-slayer</b>: <r v=\"1Tim.1.9\"></r> (cf. <x><g>φονεύς</g></x>, and v. MM, <i>VGT</i>, s.v.).†</s>"},"G442":{"l":"ἀνθρώπινος","o":7,"ar":"<f><o>ἀνθρώπινος</o>، <g>-η, ον</g></f> <s><b>بشري</b>، خاص بالإنسان: <g>χεῖρες</g>، <r v=\"Acts.17.25\"></r>؛ <g>σοφία</g>، <r v=\"1Cor.2.13\"></r>؛ <g>φύσις</g>، <r v=\"Jas.3.7\"></r>؛ <g>κτίσις</g>، <r v=\"1Pet.2.13\"></r>؛ <g>ἀ. ἡμέρα</g>، عكس <g>ἡ ἡμ.</g> (<r v=\"1Cor.3.13\"></r>، يوم دينونة الله): <b>حكم بشري</b>، <r v=\"1Cor.4.3\"></r>؛ <g>πειρασμὸς ἀ.</g>، <b>تجربة يحتملها الإنسان</b>، <r v=\"1Cor.10.13\"></r>؛ <g>ἀνθρώπινον λέγω</g>، <b>أتكلم بحسب الإنسان</b>، بكلام غير موزون بدقة، <r v=\"Rom.6.19\"></r>.†</s>","en":"<f><o>ἀνθρώπινος</o>, <g>-η, ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄνθρωπος</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H120\">אָדָם</h>, <h n=\"H582\">אֱנוֹשׁ</h>;]</e> </et> <s><b>human</b>, belonging to man: <g>χεῖρες</g>, <r v=\"Acts.17.25\"></r>; <g>σοφία</g>, <r v=\"1Cor.2.13\"></r>; <g>φύσις</g>, <r v=\"Jas.3.7\"></r>; <g>κτίσις</g>, <r v=\"1Pet.2.13\"></r> (MM, <i>VGT</i>, s.v.); <g>ἀ. ἡμέρα</g>, opp. to <g>ἡ ἡμ.</g> (<r v=\"1Cor.3.13\"></r>, God's Judgment-Day), <b>human judgment</b>, <r v=\"1Cor.4.3\"></r> (v. Lft., <i>Notes</i>, 198); <g>πειρασμὸς ἀ.</g>, <b>temptation such as man can bear</b> (AV,<i> such as is common to man</i>, v. Field, <i>Notes</i>, 175), <r v=\"1Cor.10.13\"></r>; <g>ἀνθρώπινον λέγω</g>, <b>I speak in human fashion</b>, with words not properly weighed, <r v=\"Rom.6.19\"></r> (v. Field, <i>Notes</i>, 156).†</s>"},"G483":{"l":"ἀντιλέγω","o":11,"ar":"<f><o>ἀντι-λέγω</o>،</f> <s><b>ناقض</b>، <b>قاوم</b>، <b>عارض</b>؛ مطلقًا: <r v=\"Acts.28.19\"></r>، <r v=\"Rom.10.21\"></r>، <r v=\"Titus.1.9\"></r> <r v=\"Titus.2.9\"></r>؛ مع القابل، <r v=\"John.19.12\"></r>، <r v=\"Acts.13.45\"></r>؛ مع المنصوب والمصدر، <r v=\"Luke.20.27\"></r>؛ المبني للمجهول، <r v=\"Luke.2.34\"></r>، <r v=\"Acts.28.22\"></r>.†</s>","en":"<f><o>ἀντι-λέγω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Hos.4.4\"></r> (<h n=\"H7378\">רִיב</h> hi.), <r v=\"Isa.50.5\"></r> (<h n=\"H5472\">סוּג</h> ni.) <r v=\"Isa.22.22\"></r> <r v=\"Isa.65.2\"></r>, <r v=\"Sir.4.25\"></r>, <r v=\"3Macc.2.28\"></r>, <r v=\"4Macc.4.7\"></r> <r v=\"4Macc.8.2\"></r>*;]</e> </et> <s><b>contradict</b>, <b>oppose</b>, <b>resist</b> (v. Field, <i>Notes</i>, 106; MM, <i>VGT</i>, s.v.); absol.: <r v=\"Acts.28.19\"></r>, <r v=\"Rom.10.21\"></r>, <r v=\"Titus.1.9\"></r> <r v=\"Titus.2.9\"></r>; c. dat., <r v=\"John.19.12\"></r>, <r v=\"Acts.13.45\"></r>; c. acc. et inf., <r v=\"Luke.20.27\"></r> T; pass., <r v=\"Luke.2.34\"></r>, <r v=\"Acts.28.22\"></r>.†</s>"},"G487":{"l":"ἀντίλυτρον","o":1,"ar":"<f>**† <o>ἀντί-λυτρον</o>، <g>-ου, τό</g>،</f> <s><b>فدية</b>: <r v=\"1Tim.2.6\"></r> (قارن <x><g>λύτρον</g></x>).†</s>","en":"<f>**† <o>ἀντί-λυτρον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in Al.: <r v=\"Ps.49.9\"></r>*;]</e> </et> <s><b>a ransom</b>: <r v=\"1Tim.2.6\"></r> (v. <i>CGT</i>, in l.; and cf. <x><g>λύτρον</g></x>).†</s>"},"G455":{"l":"ἀνοίγω","o":77,"ar":"<f><o>ἀν-οίγω</o></f> <s><b>يفتح</b>؛ <s n=\"1.\">متعدٍّ، مع المنصوب؛ عن باب أو بوابة، <r v=\"Acts.5.19\"></r>، <r v=\"Acts.12.14\"></r>، <r v=\"Rev.4.1\"></r>؛ المبني للمجهول، <r v=\"Acts.12.10\"></r>، <r v=\"Acts.16.26\"></r>، <r v=\"Acts.16.27\"></r>؛ ومجازيًا عن الفرصة أو الترحيب، <r v=\"Acts.14.27\"></r>، <r v=\"Col.4.3\"></r>، <r v=\"Rev.3.20\"></r>؛ المبني للمجهول، <r v=\"1Cor.16.9\"></r>، <r v=\"2Cor.2.12\"></r>، <r v=\"Rev.3.8\"></r>؛ مطلقًا (يُقدَّر <g>θύραν</g>)، <r v=\"Acts.5.23\"></r>، <r v=\"Acts.12.16\"></r>؛ مع القابل للشخص، <r v=\"Luke.12.36\"></r>، <r v=\"John.10.3\"></r>؛ مجازيًا، <r v=\"Matt.7.7\"></r>، <r v=\"Matt.7.8\"></r>، <r v=\"Matt.25.11\"></r>، <r v=\"Luke.11.9\"></r>، <r v=\"Luke.11.10\"></r>، <r v=\"Luke.13.25\"></r>، <r v=\"Rev.3.7\"></r>؛ <g>θησαυρούς</g> (<r v=\"Sir.43.14\"></r>)، <r v=\"Matt.2.11\"></r>؛ <g>τ. μνημεῖα</g>، <r v=\"Matt.27.52\"></r>؛ <g>τάφος</g>، <r v=\"Rom.3.13\"></r>؛ <g>τ. φρέαρ</g>، <r v=\"Rev.9.2\"></r>؛ عن السماء، <r v=\"Matt.3.16\"></r>، <r v=\"Luke.3.21\"></r>، <r v=\"Acts.10.11\"></r>، <r v=\"Rev.11.19\"></r>، <r v=\"Rev.15.5\"></r>، <r v=\"Rev.19.11\"></r>؛ <g>σφραγῖδα</g>، <r v=\"Rev.5.9\"></r>، <r v=\"Rev.6.1\"></r> وما يليه، <r v=\"Rev.8.1\"></r>؛ <g>βιβλίον</g>، <g>βιβλαρίδιον</g>، <r v=\"Luke.4.17\"></r>، <r v=\"Rev.5.2-Rev.5.5\"></r>، <r v=\"Rev.10.2\"></r>، <r v=\"Rev.10.8\"></r>، <r v=\"Rev.20.12\"></r>؛ <g>τ. στόμα</g>، <r v=\"Matt.17.27\"></r>؛ ونفسه بأسلوب عبري (<r v=\"Num.22.28\"></r>، <r v=\"Job.3.1\"></r>، <r v=\"Isa.50.5\"></r>، وفي مواضع أخرى)، عن الشروع في الكلام، <r v=\"Matt.5.2\"></r>، <r v=\"Acts.8.32\"></r>، <r v=\"Acts.8.35\"></r>، <r v=\"Acts.10.34\"></r>، <r v=\"Acts.18.14\"></r>؛ يليه <g>εἰς βλαιφημίας</g>، <r v=\"Rev.13.6\"></r>؛ <g>ἐν παραβολαῖς</g> (<r v=\"Ps.78.2\"></r>)، <r v=\"Matt.13.35\"></r>؛ عن استرداد النطق، <r v=\"Luke.1.64\"></r>؛ عن انفتاح الأرض، <r v=\"Rev.12.16\"></r>؛ <g>τ. ὀφθαλμούς</g>، <r v=\"Acts.9.8\"></r>، <r v=\"Acts.9.40\"></r>؛ ونفسه مع المضاف إليه للشخص، عن رد البصر، <r v=\"Matt.9.30\"></r>، <r v=\"Matt.20.33\"></r>، <r v=\"John.9.10\"></r> وما يليه، <r v=\"John.10.21\"></r>، <r v=\"John.11.37\"></r>؛ مجازيًا، <r v=\"Acts.26.18\"></r>؛ <g>ἀκοάς</g>، مع المضاف إليه للشخص، عن رد السمع، <r v=\"Mark.7.35\"></r>.</s> <s n=\"2.\">لازم في التام الثاني <g>ἀνέῳγα</g>؛ عن السماء، <r v=\"John.1.51\"></r>؛ <g>τ. στόμα</g>، يليه <g>πρός</g>، عن الكلام بصراحة، <r v=\"2Cor.6.11\"></r> (قارن <g>δι-ανοίγω</g>).†</s> </s>","en":"<f><o>ἀν-οίγω</o></f> <et> <e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>οἴγω</g></x> = <x><g>οἴγνυμι</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6605\">פָּתַח</h>;]</e> </et> <s><b>to open</b>; <s n=\"1.\">trans., c. acc.; a door or gate, <r v=\"Acts.5.19\"></r> <r v=\"Acts.12.14\"></r>, <r v=\"Rev.4.1\"></r>; pass., <r v=\"Acts.12.10\"></r> <r v=\"Acts.16.26\"></r>, <r v=\"Acts.16.27\"></r>; metaph. of opportunity or welcome, <r v=\"Acts.14.27\"></r>, <r v=\"Col.4.3\"></r>, <r v=\"Rev.3.20\"></r>; pass., <r v=\"1Cor.16.9\"></r>, <r v=\"2Cor.2.12\"></r>, <r v=\"Rev.3.8\"></r>; absol. (sc. <g>θύραν</g>), <r v=\"Acts.5.23\"></r> <r v=\"Acts.12.16\"></r>; c. dat. pers., <r v=\"Luke.12.36\"></r>, <r v=\"John.10.3\"></r>; metaph., <r v=\"Matt.7.7\"></r>, <r v=\"Matt.7.8\"></r> <r v=\"Matt.25.11\"></r>, <r v=\"Luke.11.9\"></r>, <r v=\"Luke.11.10\"></r> <r v=\"Luke.13.25\"></r>, <r v=\"Rev.3.7\"></r>; <g>θησαυρούς</g> (<r v=\"Sir.43.14\"></r>), <r v=\"Matt.2.11\"></r>; <g>τ. μνημεῖα</g>, <r v=\"Matt.27.52\"></r>; <g>τάφος</g>, <r v=\"Rom.3.13\"></r>; <g>τ. φρέαρ</g>, <r v=\"Rev.9.2\"></r>; of heaven, <r v=\"Matt.3.16\"></r>, <r v=\"Luke.3.21\"></r>, <r v=\"Acts.10.11\"></r>, <r v=\"Rev.11.19\"></r> <r v=\"Rev.15.5\"></r> <r v=\"Rev.19.11\"></r>; <g>σφραγῖδα</g>, <r v=\"Rev.5.9\"></r> <r v=\"Rev.6.1\"></r> ff. <r v=\"Rev.8.1\"></r>; <g>βιβλίον</g>, <g>βιβλαρίδιον</g>, <r v=\"Luke.4.17\"></r>, <r v=\"Rev.5.2-Rev.5.5\"></r> <r v=\"Rev.10.2\"></r>, <r v=\"Rev.10.8\"></r> <r v=\"Rev.20.12\"></r>; <g>τ. στόμα</g>, <r v=\"Matt.17.27\"></r>; id. Hebraistically (<r v=\"Num.22.28\"></r>, <r v=\"Job.3.1\"></r>, <r v=\"Isa.50.5\"></r>, al.), of beginning to speak, <r v=\"Matt.5.2\"></r>, <r v=\"Acts.8.32\"></r>, <r v=\"Acts.8.35\"></r> <r v=\"Acts.10.34\"></r> <r v=\"Acts.18.14\"></r>; seq. <g>εἰς βλαιφημίας</g>, <r v=\"Rev.13.6\"></r>; <g>ἐν παραβολαῖς</g> (<r v=\"Ps.78.2\"></r>), <r v=\"Matt.13.35\"></r>; of recovering speech, <r v=\"Luke.1.64\"></r>; of the earth opening, <r v=\"Rev.12.16\"></r>; <g>τ. ὀφθαλμούς</g>, <r v=\"Acts.9.8\"></r>, <r v=\"Acts.9.40\"></r>; id. c. gen. pers., of restoring sight, <r v=\"Matt.9.30\"></r> <r v=\"Matt.20.33\"></r>, <r v=\"John.9.10\"></r> ff. <r v=\"John.10.21\"></r> <r v=\"John.11.37\"></r>; metaph., <r v=\"Acts.26.18\"></r>; <g>ἀκοάς</g>, c. gen. pers., of restoring hearing, <r v=\"Mark.7.35\"></r>.</s> <s n=\"2.\">Intrans. in 2 pf., <g>ἀνέῳγα</g> (M, <i>Pr.</i>, 154); heaven, <r v=\"John.1.51\"></r>; <g>τ. στόμα</g>, seq. <g>πρός</g>, of speaking freely, <r v=\"2Cor.6.11\"></r> (cf. <g>δι-ανοίγω</g> and v. MM, <i>VGT</i>, 45).†</s> </s>"},"G482":{"l":"ἀντιλαμβάνω","o":3,"ar":"<f><o>ἀντι-λαμβάνω</o>،</f> <s><b>يأخذ بدلًا من</b> أو <b>بالمقابل</b>. والصيغة الوسطى مع المضاف إليه: <b>يُمسك بـ</b>؛ <s n=\"(a)\">عن الأشخاص، <b>يُعين، يعضد</b>: <r v=\"Luke.1.54\"></r>، <r v=\"Acts.20.35\"></r>؛</s> <s n=\"(b)\">عن الأشياء، <b>يشترك في</b>: <r v=\"1Tim.6.2\"></r> (قارن <g>συν-αντιλαμβάνω</g>).†</s> </s>","en":"<f><o>ἀντι-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[freq. in LXX for <h n=\"H2388\">חזק</h> hi., <h n=\"H5564\">תּמךְ</h>, etc;]</e> </et> <s><b>to take instead of</b> or <b>in turn</b>. Mid., c. gen., <b>to take hold of</b>; <s n=\"(a)\">of persons, <b>to help</b> (v. MM, <i>VGT</i>, s.v.): <r v=\"Luke.1.54\"></r>, <r v=\"Acts.20.35\"></r>;</s> <s n=\"(b)\">of things, <b>to partake of</b>: <r v=\"1Tim.6.2\"></r> (v. Field, <i>Notes</i>, 210; Cremer, 386; and cf. <g>συν-αντιλαμβάνω</g>).†</s> </s>"},"G484":{"l":"ἀντίλημψις","o":1,"ar":"<f><o>ἀντί-λημψις</o>، <g>-εως</g>، <g>ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>الإمساك بـ</b>، <b>المبادلة</b>.</s> <s n=\"2.\">في اليونانية المتأخرة (والسبعينية): <b>عون</b>؛ وبالجمع عن خدمات الشمامسة: <r v=\"1Cor.12.28\"></r>.†</s>","en":"<f><o>ἀντί-λημψις</o>, (Rec. <g>-ληψις</g>; v. MM, <i>VGT</i> s.v.; M, <i>Pr.</i>, 56), <g>-εως</g>, <g>ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀντιλαμβάνομαι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5797\">עֹז</h>, <h n=\"H2220\">זְרוֹעַ</h>, etc., freq. in Pss and II, III Mac.; freq. also in <g>π.</g> in petitions to the Ptolemies in sense of <g>βοήθεια</g> (v. Deiss., <i>LAE</i>, 107; <b>BS</b>, 92, 223);]</e> </et> <s n=\"1.\">cl. <b>a laying hold of</b>, <b>an exchange</b>.</s> <s n=\"2.\">Hellenistic (LXX, <g>π.</g>) help: pl. of ministrations of deacons; <r v=\"1Cor.12.28\"></r> (<i>DB</i>, ii, 347 f.; Cremer, 386).†</s>"},"G404":{"l":"ἀναψύχω","o":1,"ar":"<f><o>ἀνα-ψύχω</o>،</f> <s><b>يُريح، يُنعش</b>: مع المنصوب للشخص، <r v=\"2Tim.1.16\"></r>.†</s>","en":"<f><o>ἀνα-ψύχω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5314\">נפשׁ</h> ni., <h n=\"H2421\">חיה</h>, etc. (freq. in sense of <i>revive</i>, <i>refresh oneself</i>);]</e> </et> <s><b>to refresh</b>: c. acc. pers., <r v=\"2Tim.1.16\"></r> (MM, <i>VGT</i>, s.v.; Cremer, 588).†</s>"},"G460":{"l":"ἀνόμως","o":2,"ar":"<f>** <o>ἀνόμως</o>،</f> ظرف <s n=\"1.\"><b>بلا ناموس، تعدّيًا على الناموس</b> (<r v=\"2Macc.8.17\"></r>).</s> <s n=\"2.\">= <g>χωρὶς νόμου</g>: <b>بدون ناموس</b>: <r v=\"Rom.2.12\"></r>.†</s>","en":"<f>** <o>ἀνόμως</o>,</f> adv. <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.17\"></r>*;]</e> </et> <s n=\"1.\"><b>lawlessly</b> (<r v=\"2Macc.8.17\"></r>).</s> <s n=\"2.\">= <g>χωρὶς νόμου</g>, <b>without law</b>: <r v=\"Rom.2.12\"></r>.†</s>"},"G443":{"l":"ἀνθρωποκτόνος","o":3,"ar":"<f>* <o>ἀνθρωποκτόνος</o>، <g>-ον</g></f> <s><b>قاتل</b>، <b>قاتل نفس، قتّال للناس</b>: <r v=\"John.8.44\"></r>، <r v=\"1John.3.16\"></r>.†</s>","en":"<f>* <o>ἀνθρωποκτόνος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>κτείνω</g></x>, <i>to kill</i>),</e> </et> <s><b>a murderer</b>, <b>manslayer</b> (Eur.; v. MM, <i>VGT</i>, s.v.): <r v=\"John.8.44\"></r>, <r v=\"1John.3.16\"></r>.†</s> <sy><i>SYN.</i>: <x><g>φονεύς</g></x>, <x><g>ἀνδροφόνος</g></x> (v. Tr., Syn, § lxxxiii).</sy>"},"G485":{"l":"ἀντιλογία","o":4,"ar":"<f><o>ἀντιλογία</o>، <g>-ας ἡ</g></f> <s><b>معارضة في الكلام</b>، <b>مشاجرة</b>: <r v=\"Heb.6.16\"></r> <r v=\"Heb.7.7\"></r> <r v=\"Heb.12.3\"></r>، <r v=\"Jude.1.11\"></r>.†</s>","en":"<f><o>ἀντιλογία</o>, <g>-ας ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀντιλέγω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7379\">רִיב</h>;]</e> </et> <s><b>gain-saying</b>, <b>strife</b> (the latter sense being found in <g>π.</g>; v. MM, <i>VGT</i>, s.v.; cf. Field, <i>Notes</i>, 106): <r v=\"Heb.6.16\"></r> <r v=\"Heb.7.7\"></r> <r v=\"Heb.12.3\"></r>, <r v=\"Jude.1.11\"></r>.†</s>"},"G476":{"l":"ἀντίδικος","o":5,"ar":"<f><o>ἀντίδικος</o>، <g>-ον</g></f> <s>اسمًا: <b>خصم في دعوى قضائية</b>، <b>خصم</b>: <r v=\"Matt.5.25\"></r>، <r v=\"Luke.12.58\"></r> <r v=\"Luke.18.3\"></r>، <r v=\"1Pet.5.8\"></r>.†</s>","en":"<f><o>ἀντίδικος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>δίκη</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7378\">רִיב</h>;]</e> </et> <s>as subst., <b>an opponent in a lawsuit</b>, <b>adversary</b>: <r v=\"Matt.5.25\"></r>, <r v=\"Luke.12.58\"></r> <r v=\"Luke.18.3\"></r>, <r v=\"1Pet.5.8\"></r> (Cremer, 696; MM, <i>VGT</i>, s.v.).†</s>"},"G412":{"l":"ἀνεκλάλητος","o":1,"ar":"<f>*† <o>ἀν-εκ-λάλητος</o>، <g>-ον</g></f> <s><b>لا يُنطَق به</b>: <r v=\"1Pet.1.8\"></r>.†</s>","en":"<f>*† <o>ἀν-εκ-λάλητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g>, <x><g>ἐκλαλέω</g></x>),</e> </et> <s><b>unspeakable</b>: <r v=\"1Pet.1.8\"></r>.†</s>"},"G461":{"l":"ἀνορθόω","o":3,"ar":"<f><o>ἀν-ορθόω</o>، <g>-ῶ</g></f> <s><b>أقام منتصبًا أو مستقيمًا من جديد</b>، <b>ردّ، رمّم</b>: عن الأشخاص، <r v=\"Luke.13.13\"></r>، <r v=\"Heb.12.12\"></r>؛ عن الأشياء، <g>σκηνήν</g>، <r v=\"Acts.15.16\"></r>.†</s>","en":"<f><o>ἀν-ορθόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>ὀρθόω</g></x>, <i>to set straight</i>, <i>set up</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3559\">כּוּן</h> hi.;]</e> </et> <s><b>to set upright or straight again</b>, <b>restore</b>: of persons, <r v=\"Luke.13.13\"></r>, <r v=\"Heb.12.12\"></r>; of things, <g>σκηνήν</g>, <r v=\"Acts.15.16\"></r> (MM, <i>VGT</i>, s.v.; Cremer, 807).†</s>"},"G401":{"l":"ἀνάχυσις","o":1,"ar":"<f>*† <o>ἀνά-χυσις</o>، <g>-εως, ἡ</g></f> <s><b>انسكاب</b>، <b>فيضان</b>، <b>إفراط</b>: مجازيًا، <r v=\"1Pet.4.4\"></r>.†</s>","en":"<f>*† <o>ἀνά-χυσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναχέω</g></x>, <i>to pour out</i>),</e> </et> <s><b>a pouring out</b>, <b>overflowing</b>, <b>excess</b>: metaph., <r v=\"1Pet.4.4\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G416":{"l":"ἀνεμίζω","o":1,"ar":"<f>*† <o>ἀνεμίζω</o> = <g>ἀνεμόω</g> في الأتيكية</f> <s>المبني للمجهول، <b>تخبطه الريح</b>: <r v=\"Jas.1.6\"></r>.†</s>","en":"<f>*† <o>ἀνεμίζω</o> = Attic <g>ἀνεμόω</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄνεμος</g></x>);</e> </et> <s>pass., <b>to be driven by the wind</b>: <r v=\"Jas.1.6\"></r>.†</s>"},"G438":{"l":"ἄνθος","o":4,"ar":"<f><o>ἄνθος</o>، <g>-εος, τό</g>،</f> <s><b>زهر</b>: <r v=\"Jas.1.10\"></r>، <r v=\"Jas.1.11\"></r>، <r v=\"1Pet.1.24\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>ἄνθος</o>, <g>-εος, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6731\">צִיץ</h>, etc.;]</e> </et> <s><b>a flower</b>: <r v=\"Jas.1.10\"></r>, <r v=\"Jas.1.11\"></r>, <r v=\"1Pet.1.24\"></r><i>(LXX)</i>.†</s>"},"G427":{"l":"ἄνευ","o":3,"ar":"<f><o>ἄνευ</o>،</f> <e t=\"derivation\">حرف جر مع المضاف إليه (أقل استعمالاً من <x><g>χωρίς</g></x>، انظره؛ قارن <r v=\"Eph.2.12\"></r>)،</e> <s><b>بدون</b>، <b>بلا</b>: <r v=\"Matt.10.29\"></r>، <r v=\"1Pet.3.1\"></r> <r v=\"1Pet.4.9\"></r>.†</s>","en":"<f><o>ἄνευ</o>,</f> <e t=\"derivation\">prep. c. gen. (rarer than <x><g>χωρίς</g></x>, q.v.; cf. Ellic. on <r v=\"Eph.2.12\"></r>; MM, <i>VGT</i>, 42),</e> <s><b>without</b>: <r v=\"Matt.10.29\"></r>, <r v=\"1Pet.3.1\"></r> <r v=\"1Pet.4.9\"></r>.†</s>"},"G464":{"l":"ἀνταγωνίζομαι","o":1,"ar":"<f>** <o>ἀντ-αγωνίζομαι</o>، فعل لازم الصيغة الوسطى،</f> <s><b>جاهد ضد</b>، <b>قاوم</b>: يليه <g>πρός</g>، مع المنصوب، <r v=\"Heb.12.4\"></r>.†</s>","en":"<f>** <o>ἀντ-αγωνίζομαι</o>, depon.,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.17.14\"></r>*;]</e> </et> <s><b>to struggle against</b>: seq. <g>πρός</g>, c. acc., <r v=\"Heb.12.4\"></r>.†</s>"},"G486":{"l":"ἀντιλοιδορέω","o":1,"ar":"<f>* <o>ἀντι-λοιδορέω</o>، <g>-ῶ</g>،</f> <s><b>شتم بالمقابل</b>، <b>ردّ الشتيمة</b>: <r v=\"1Pet.2.23\"></r>.†</s>","en":"<f>* <o>ἀντι-λοιδορέω</o>, <g>-ῶ</g>,</f> <s><b>to revile in turn</b>: <r v=\"1Pet.2.23\"></r>.†</s>"},"G499":{"l":"ἀντίτυπος","o":2,"ar":"<f>** <o>ἀντί-τυπος</o>، <g>-ον</g></f> <s n=\"1.\">المبني للمعلوم: <b>ضارب بالمقابل</b>؛ مجازيًا، <b>مقاوم</b>، <b>معاكس</b>.</s> <s n=\"2.\">المبني للمجهول: <b>مضروب بالمقابل</b>؛ مجازيًا، <b>مطابق لـ، مماثل</b>؛ <s n=\"(a)\">كالطبعة من الختم أو النسخة من الأصل (<g>τύπος</g>)، <r v=\"Heb.9.24\"></r>؛</s> <s n=\"(b)\">كالحقيقة (التي يكون <g>τύπος</g> نسختها أو ظلها)، <r v=\"1Pet.3.21\"></r>.†</s> </s>","en":"<f>** <o>ἀντί-τυπος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(v.s. <x><g>τύπος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.3.13\"></r> A*;]</e> </et> <s n=\"1.\">act. <b>striking back</b>; metaph., <b>resisting</b>, <b>adverse</b>.</s> <s n=\"2.\">Pass. <b>struck back</b>; metaph., <b>corresponding to</b> (MM, <i>VGT</i>, s.v.); <s n=\"(a)\">as impression of a seal or copy of an archetype (<g>τύπος</g>) (RV, <i>like in pattern</i>), <r v=\"Heb.9.24\"></r>;</s> <s n=\"(b)\">as the reality (of which <g>τύπος</g> is the copy or adumbration) (RV, <i>after a true likeness</i>), <r v=\"1Pet.3.21\"></r> (Cremer, 357).†</s> </s>"},"G478":{"l":"ἀντικαθίστημι","o":1,"ar":"<f><o>ἀντι-καθ-ίστημι</o>،</f> <s n=\"1.\">بمعنى السببية في المضارع والماضي الناقص والمستقبل والماضي البسيط الأول: <b>أقام بدلاً من</b>، <b>أقام في مواجهة</b>.</s> <s n=\"2.\">لازم في المبني للمجهول والماضي البسيط الثاني المبني للمعلوم؛ <s n=\"(a)\"><b>حلّ محلّ</b>؛</s> <s n=\"(b)\"><b>قاوم</b>: <r v=\"Heb.12.4\"></r>.†</s> </s>","en":"<f><o>ἀντι-καθ-ίστημι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.31.21\"></r> (<h n=\"H6030\">ענה</h>), <r v=\"Josh.5.7\"></r>, <r v=\"Mic.2.8\"></r> (<h n=\"H6965\">קוּם</h>)*;]</e> </et> <s n=\"1.\">causal in pres. impf. fut. and 1 aor.; <b>to replace</b>, <b>oppose</b>.</s> <s n=\"2.\">Intrans. in pass. and 2 aor. act.; <s n=\"(a)\"><b>to supersede</b>;</s> <s n=\"(b)\"><b>to resist</b>: <r v=\"Heb.12.4\"></r>.†</s> </s>"},"G448":{"l":"ἀνέλεος","o":null,"ar":"<f>*† <o>ἀν-έλεος</o>، <g>-ον</g></f> <s><b>بلا رحمة</b>: <r v=\"Jas.2.13\"></r>.†</s>","en":"<f>*† <o>ἀν-έλεος</o>, <g>-ον</g> (Attic <g>ἀνηλεής</g>, <g>ἀνελεήμων</g>; MM, <i>VGT</i>, s.v.),</f> <s><b>merciless</b>: <r v=\"Jas.2.13\"></r>.†</s>"},"G493":{"l":"Ἀντίπας","o":1,"ar":"<f><o>Ἀντίπας</o>، <g>-α</g> (يبدو في بعض المخطوطات أنه لا يُصرَّف؛ قارن <r v=\"Prov.12.1-Prov.12.28\"></r>؛ وهو مختصر من <x><g>Ἀντίπατρος</g></x>)، <g>ὁ</g>،</f> <s><b>أنتيباس</b>: <r v=\"Rev.2.13\"></r>.†</s>","en":"<f><o>Ἀντίπας</o> (T, <g>Ἀντείπας</g>), <g>-α</g> (in some MSS. it appears to be indecl.; but v. M, <r v=\"Prov.12.1-Prov.12.28\"></r>; it is abbrev. from <x><g>Ἀντίπατρος</g></x>), <g>ὁ</g>,</f> <s><b>Antipas</b>: <r v=\"Rev.2.13\"></r>.†</s>"},"G402":{"l":"ἀναχωρέω","o":14,"ar":"<f><o>ἀνα-χωρέω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>رجع</b>.</s> <s n=\"2.\"><b>انصرف، انسحب</b>: <r v=\"Matt.9.24\"></r>؛ كثيرًا بمعنى تجنُّب الخطر، <r v=\"Matt.2.12\"></r>، <r v=\"Matt.2.13\"></r>، <r v=\"Matt.2.14\"></r>، <r v=\"Matt.2.22\"></r>، <r v=\"Matt.4.12\"></r>، <r v=\"Matt.12.15\"></r>، <r v=\"Matt.14.13\"></r>، <r v=\"Matt.15.21\"></r>، <r v=\"Matt.27.5\"></r>، <r v=\"Mark.3.7\"></r>، <r v=\"John.6.15\"></r>، <r v=\"Acts.23.19\"></r>، <r v=\"Acts.26.31\"></r>.†</s>","en":"<f><o>ἀνα-χωρέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1272\">בּרח</h>, <h n=\"H5123\">נוּם</h>, etc.;]</e> </et> <s n=\"1.\"><b>to go back</b>.</s> <s n=\"2.\"><b>to withdraw</b>: <r v=\"Matt.9.24\"></r>; freq. in sense of avoiding danger (MM, <i>VGT</i>, s.v.), <r v=\"Matt.2.12\"></r> (but v. Thayer), <r v=\"Matt.2.13\"></r>, <r v=\"Matt.2.14\"></r>, <r v=\"Matt.2.22\"></r> <r v=\"Matt.4.12\"></r> <r v=\"Matt.12.15\"></r> <r v=\"Matt.14.13\"></r> <r v=\"Matt.15.21\"></r> <r v=\"Matt.27.5\"></r>, <r v=\"Mark.3.7\"></r>, <r v=\"John.6.15\"></r>, <r v=\"Acts.23.19\"></r> <r v=\"Acts.26.31\"></r>.†</s>"},"G400":{"l":"ἀναφωνέω","o":1,"ar":"<f><o>ἀνα-φωνέω</o>، <g>-ῶ</g>،</f> <s><b>صرخ</b>، <b>هتف</b>: <r v=\"Luke.1.42\"></r>.†</s>","en":"<f><o>ἀνα-φωνέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8085\">שׁמע</h> hi., <h n=\"H2142\">זכר</h> hi.;]</e> </et> <s><b>to cry out</b>, <b>exclaim</b>: <r v=\"Luke.1.42\"></r> (Arist., al.).†</s>"},"G406":{"l":"Ἀνδρέας","o":13,"ar":"<f><o>Ἀνδρέας</o>، <g>-ου, ὁ</g>،</f> <s><b>أندراوس</b>، الرسول: <r v=\"Matt.4.18\"></r> <r v=\"Matt.10.2\"></r>، <r v=\"Mark.1.16\"></r>، <r v=\"Mark.1.29\"></r> <r v=\"Mark.3.18\"></r> <r v=\"Mark.13.3\"></r>، <r v=\"Luke.6.14\"></r>، <r v=\"John.1.41\"></r>، <r v=\"John.1.45\"></r> <r v=\"John.6.8\"></r> <r v=\"John.12.22\"></r>، <r v=\"Acts.1.13\"></r>.†</s>","en":"<f><o>Ἀνδρέας</o>, <g>-ου, ὁ</g>,</f> <s><b>Andrew</b>, the Apostle: <r v=\"Matt.4.18\"></r> <r v=\"Matt.10.2\"></r>, <r v=\"Mark.1.16\"></r>, <r v=\"Mark.1.29\"></r> <r v=\"Mark.3.18\"></r> <r v=\"Mark.13.3\"></r>, <r v=\"Luke.6.14\"></r>, <r v=\"John.1.41\"></r>, <r v=\"John.1.45\"></r> <r v=\"John.6.8\"></r> <r v=\"John.12.22\"></r>, <r v=\"Acts.1.13\"></r>.†</s>"},"G414":{"l":"ἀνεκτός","o":null,"ar":"<f>* <o>ἀν-εκτός</o>، <g>-όν</g></f> <s><b>محتمَل</b>: صيغة التفضيل، <g>-ότερος</g>، <r v=\"Matt.10.15\"></r> <r v=\"Matt.11.22\"></r>، <r v=\"Matt.11.24\"></r>، <r v=\"Luke.10.12\"></r>، <r v=\"Luke.10.14\"></r>.†</s>","en":"<f>* <o>ἀν-εκτός</o>, <g>-όν</g></f> <et> <e t=\"derivation\">(also in late Gk. <g>-ή</g>, <g>-όν</g>; &lt; <x><g>ἀνέχομαι</g></x>),</e> </et> <s><b>tolerable</b>: compar., <g>-ότερος</g>, <r v=\"Matt.10.15\"></r> <r v=\"Matt.11.22\"></r>, <r v=\"Matt.11.24\"></r>, <r v=\"Luke.10.12\"></r>, <r v=\"Luke.10.14\"></r>.†</s>"},"G446":{"l":"ἀνθύπατος","o":5,"ar":"<f>* <o>ἀνθ-ύπατος</o>، <g>-ου, ὁ</g></f> <s><b>أعلى</b>، <b>قنصل</b>، مَن يقوم مقام القنصل، <b>والٍ (بروقنصل)</b>، حاكم ولاية تابعة لمجلس الشيوخ (قارن <x><g>ἡγεμών</g></x>): <r v=\"Acts.13.7\"></r>، <r v=\"Acts.13.8\"></r>، <r v=\"Acts.13.12\"></r> <r v=\"Acts.18.12\"></r> <r v=\"Acts.19.38\"></r>.†</s>","en":"<f>* <o>ἀνθ-ύπατος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ὕπατος</g></x>, altern. for <x><g>ὑπέρτατος</g></x>),</e> </et> <s><b>supreme</b>, <b>a consul</b>, one acting in place of a consul, <b>a proconsul</b>, the administrator of a senatorial province (cf. <x><g>ἡγεμών</g></x>, and v. MM, <i>VGT</i>, 44): <r v=\"Acts.13.7\"></r>, <r v=\"Acts.13.8\"></r>, <r v=\"Acts.13.12\"></r> <r v=\"Acts.18.12\"></r> <r v=\"Acts.19.38\"></r>.†</s>"},"G465":{"l":"ἀντάλλαγμα","o":2,"ar":"<f><o>ἀντ-άλλαγμα</o>، <g>-τος, τό</g></f> <s><b>مقايضة، عِوَض</b>، الثمن المأخوذ مقابل سلعة تجارية: <r v=\"Matt.16.26\"></r>، <r v=\"Mark.8.37\"></r> (قارن <r v=\"Sir.26.14\"></r>؛ وقارن <r v=\"Mark.8.37\"></r>).†</s>","en":"<f><o>ἀντ-άλλαγμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ἄλλαγμα</g></x>; &lt; <x><g>ἀλλάσσω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4242\">מְחִיר</h>;]</e> </et> <s><b>an exchange</b>, the price received as an equivalent for an article of commerce: <r v=\"Matt.16.26\"></r>, <r v=\"Mark.8.37\"></r> (cf. <r v=\"Sir.26.14\"></r>; and v. Swete, <r v=\"Mark.8.37\"></r>; Cremer, 90).†</s>"},"G413":{"l":"ἀνέκλειπτος","o":1,"ar":"<f>* <o>ἀνέκλειπτος</o>، <g>-ον</g></f> <s><b>لا يفنى</b> (لا ينفد): <r v=\"Luke.12.33\"></r>.†</s>","en":"<f>* <o>ἀνέκλειπτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g>, <x><g>ἐκλείπω</g></x>),</e> </et> <s><b>unfailing</b>: <r v=\"Luke.12.33\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G479":{"l":"ἀντικαλέω","o":1,"ar":"<f>* <o>ἀντι-καλέω</o>، <g>-ῶ</g>،</f> <s><b>يدعو بالمقابل</b>: <r v=\"Luke.14.12\"></r>.†</s>","en":"<f>* <o>ἀντι-καλέω</o>, <g>-ῶ</g>,</f> <s><b>to invite in turn</b>: <r v=\"Luke.14.12\"></r>.†</s>"},"G495":{"l":"ἀντίπερα","o":1,"ar":"<f>*† <o>ἀντί-περα</o>، ظرف، = <g>ἀντιπέρας</g> في الكلاسيكية،</f> <s><b>في الجانب المقابل</b>: مع المضاف إليه، <r v=\"Luke.8.26\"></r>.†</s>","en":"<f>*† <o>ἀντί-περα</o> (Rec. <g>ἀντιπέραν</g>, LTr. <g>ἀντιπέρα</g>,) adv., = cl. <g>ἀντιπέρας</g> (MM, <i>VGT</i>, 49),</f> <s><b>on the opposite side</b>: c. gen., <r v=\"Luke.8.26\"></r>.†</s>"},"G432":{"l":"ἄνηθον","o":1,"ar":"<f>* <o>ἄνηθον</o>، <g>-ου, τό</g>،</f> <s><b>الشِّبِث</b> (الينسون): <r v=\"Matt.23.23\"></r>.†</s>","en":"<f>* <o>ἄνηθον</o>, <g>-ου, τό</g>,</f> <s><b>anise</b>: <r v=\"Matt.23.23\"></r>.†</s>"},"G437":{"l":"ἀνθομολογέομαι","o":1,"ar":"<f><o>ἀνθ-ομολογέομαι</o>، <g>-οῦμαι</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>عقد اتفاقًا متبادلاً</b>.</s> <s n=\"2.\">عند الكتّاب المتأخرين: <b>اعترف تمامًا</b>، <b>أقرّ</b> (قارن <r v=\"1Esd.8.91\"></r>).</s> <s n=\"3.\">مع القابل للشخص: <b>أعلن تسبيحه</b>، تكلّم بإسهاب في الصلاة أو الشكر، <b>شكر</b> (قارن <r v=\"Ps.79.13\"></r>): <r v=\"Luke.2.38\"></r>.†</s>","en":"<f><o>ἀνθ-ομολογέομαι</o>, <g>-οῦμαι</g></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>ὁμολογέομαι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.79.13\"></r> (<h n=\"H3034\">יָדָה</h>), <r v=\"Dan.4.34\"></r> (<h n=\"H7624\">שְׁבַּח</h>), <r v=\"1Esd.8.91\"></r>, <r v=\"Sir.20.2\"></r>, <r v=\"3Macc.6.33\"></r>*;]</e> </et> <s n=\"1.\"><b>to make a mutual agreement</b> (Dem., Polyb.).</s> <s n=\"2.\"><b>to acknowledge fully</b>, <b>confess</b> (Diod., Polyb., cf. <r v=\"1Esd.8.91\"></r>).</s> <s n=\"3.\">C. dat. pers., <b>to declare one's praises</b>, speak fully in prayer or thanksgiving, <b>give thanks to</b> (cf. <r v=\"Ps.79.13\"></r>): <r v=\"Luke.2.38\"></r> (Cremer, 771; MM, <i>VGT</i>, s.v.).†</s>"},"G452":{"l":"Ἄννας","o":4,"ar":"<f><o>Ἄννας</o>، <g>-α</g>، <g>ὁ</g> (العبرية <h n=\"H2603\">חָנַן</h>)،</f> <s><b>حنّان</b>، رئيس الكهنة: <r v=\"Luke.3.2\"></r>، <r v=\"John.18.13\"></r>، <r v=\"John.18.24\"></r>، <r v=\"Acts.4.6\"></r>.†</s>","en":"<f><o>Ἄννας</o>, <g>-α</g> (FlJ, <g>Ἄνανος</g>, <g>-ου</g>), <g>ὁ</g> (Heb. <h n=\"H2603\">חָנַן</h>),</f> <s><b>Annas</b>, the high priest: <r v=\"Luke.3.2\"></r>, <r v=\"John.18.13\"></r>, <r v=\"John.18.24\"></r>, <r v=\"Acts.4.6\"></r>.†</s>"},"G492":{"l":"ἀντιπαρέρχομαι","o":2,"ar":"<f>**† <o>ἀντι-παρ-έρχομαι</o>،</f> <s><b>جاز مقابله</b>: <r v=\"Luke.10.31\"></r>، <r v=\"Luke.10.32\"></r>.†</s>","en":"<f>**† <o>ἀντι-παρ-έρχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.16.10\"></r>*;]</e> </et> <s><b>to pass by opposite to</b>: <r v=\"Luke.10.31\"></r>, <r v=\"Luke.10.32\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G456":{"l":"ἀνοικοδομέω","o":2,"ar":"<f><o>ἀν-οικο-δομέω</o>، <g>-ῶ</g>،</f> <s><b>بنى ثانيةً</b>، <b>أعاد البناء</b>: <r v=\"Acts.15.16\"></r>.†</s>","en":"<f><o>ἀν-οικο-δομέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1129\">בּנה</h>, <h n=\"H1443\">גּדר</h>;]</e> </et> <s><b>to build again</b>, <b>rebuild</b> (MM, <i>VGT</i>, s.v.): <r v=\"Acts.15.16\"></r>.†</s>"},"G474":{"l":"ἀντιβάλλω","o":1,"ar":"<f>** <o>ἀντι-βάλλω</o>،</f> <s><b>ألقى بالتبادل</b>، <b>تبادل</b>: مجازيًا، <g>λόγους</g> (قارن باللاتينية <l>conferre sermones</l>)، <r v=\"Luke.24.17\"></r>.†</s>","en":"<f>** <o>ἀντι-βάλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.11.13\"></r>*;]</e> </et> <s><b>to throw in turn</b>, <b>exchange</b>: metaph., <g>λόγους</g> (cf. Lat. <l>conferre sermones</l>; v. Field, <i>Notes</i>, 81), <r v=\"Luke.24.17\"></r>.†</s>"},"G494":{"l":"Ἀντιπατρίς","o":1,"ar":"<f><o>Ἀντιπατρίς</o>، <g>-ίδος, ἡ</g>،</f> <s><b>أنتيباتريس</b>، بين يافا وقيصرية: <r v=\"Acts.23.31\"></r>.†</s>","en":"<f><o>Ἀντιπατρίς</o>, <g>-ίδος, ἡ</g>,</f> <s><b>Antipatris</b>, bet. Joppa and Caesarea: <r v=\"Acts.23.31\"></r>.†</s>"},"G418":{"l":"ἀνένδεκτος","o":1,"ar":"<f>*† <o>ἀν-ένδεκτος</o>، <g>-ον</g></f> <s><b>مستحيل</b>، <b>غير ممكن القبول</b>: <r v=\"Luke.17.1\"></r>.†</s>","en":"<f>*† <o>ἀν-ένδεκτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀ-</g> neg., <x><g>ἔνδεκτος</g></x>; &lt; <x><g>ἐνδέχομαι</g></x>),</e> </et> <s><b>impossible</b>, <b>inadmissible</b>: <r v=\"Luke.17.1\"></r>.†</s>"},"G426":{"l":"ἀνετάζω","o":2,"ar":"<f>† <o>ἀν-ετάζω</o></f> <s><b>فحص قضائيًا (استجوب)</b>: <r v=\"Acts.22.24\"></r>، <r v=\"Acts.22.29\"></r>.†</s>","en":"<f>† <o>ἀν-ετάζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνά</g></x>, <x><g>ἐτάζω</g></x>, <i>to examine</i>; v. MM, <i>VGT</i>, s.v.),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.6.29\"></r> (<h n=\"H1875\">דָּרַשׁ</h>), <r v=\"Ezra.2.23\"></r> (<h n=\"H1245\">בָּקַשׁ</h>), <r v=\"Sus.1.14\"></r>*;]</e> </et> <s><b>to examine judicially</b>: <r v=\"Acts.22.24\"></r>, <r v=\"Acts.22.29\"></r>.†</s>"},"G451":{"l":"Ἄννα","o":1,"ar":"<f><o>Ἄννα</o>، <g>-ας, ἡ</g> (بالعبرية <h n=\"H2583\">חָנָּה</h>)،</f> <s><b>حنة</b>، نبيّة: <r v=\"Luke.2.36\"></r>.†</s>","en":"<f><o>Ἄννα</o>, <g>-ας, ἡ</g> (Heb. <h n=\"H2583\">חָנָּה</h>),</f> <s><b>Anna</b>, a prophetess: <r v=\"Luke.2.36\"></r>.†</s>"},"G439":{"l":"ἀνθρακιά","o":2,"ar":"<f>** <o>ἀνθρακιά</o>، <g>-ᾶς, ἡ</g></f> <s><b>كومة من الجمر المتّقد</b>: <r v=\"John.18.18\"></r> <r v=\"John.21.9\"></r>.†</s>","en":"<f>** <o>ἀνθρακιά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄνθραξ</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.11.32\"></r>, <r v=\"4Macc.9.20\"></r>*;]</e> </et> <s><b>a heap of burning coals</b>: <r v=\"John.18.18\"></r> <r v=\"John.21.9\"></r>.†</s>"},"G491":{"l":"Ἀντιοχεύς","o":1,"ar":"<f><o>Ἀντιοχεύς</o>، <g>-έως, ὁ</g>،</f> <s><b>مواطن من أنطاكية</b>، <b>أنطاكي</b>: <r v=\"Acts.6.5\"></r>.†</s>","en":"<f><o>Ἀντιοχεύς</o>, <g>-έως, ὁ</g>,</f> <s><b>a citizen of Antioch</b>, <b>an Antiochian</b>: <r v=\"Acts.6.5\"></r>.†</s>"},"G403":{"l":"ἀνάψυξις","o":1,"ar":"<f><o>ἀνά-ψυξις</o>، <g>-εως, ἡ</g></f> <s><b>انتعاش، فرج</b>: <r v=\"Acts.3.19\"></r>.†</s>","en":"<f><o>ἀνά-ψυξις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναψύχω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.8.15\"></r> (<r v=\"Exod.8.11\"></r> (<h n=\"H7309\">רְוָחָה</h>)*;]</e> </et> <s><b>a refreshing</b>: <r v=\"Acts.3.19\"></r>.†</s>"},"G471":{"l":"ἀντεῖπον","o":null,"ar":"<f><o>ἀντ-ε͂ιπον</o></f> <s>ماضٍ بسيط ثانٍ، لا مضارع مستعمل له، <b>قاوم بالكلام</b>، <b>ناقض</b>: <r v=\"Luke.21.15\"></r>، <r v=\"Acts.4.14\"></r>.†</s>","en":"<f><o>ἀντ-ε͂ιπον</o></f> <et> <e t=\"derivation\">(<x><g>ἀντί</g></x>, <x><g>εἶπον</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H7725\">שׁוּב</h> hi., <h n=\"H1696\">דבר</h> pi., <h n=\"H6030\">ענה</h>, etc.;]</e> </et> <s>2 aor., without present in use, <b>to speak against</b>, <b>gainsay</b>: <r v=\"Luke.21.15\"></r>, <r v=\"Acts.4.14\"></r>.†</s>"},"G496":{"l":"ἀντιπίπτω","o":1,"ar":"<f><o>ἀντι-πίπτω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سقط على</b> أو <b>اصطدم بـ</b>.</s> <s n=\"2.\"><b>قاوم</b>، <b>عاند</b>: مع القابل، <r v=\"Acts.7.51\"></r>.</s>","en":"<f><o>ἀντι-πίπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.26.5\"></r> (<h n=\"H6901\">קבל</h>), <r v=\"Exod.26.17\"></r> (<h n=\"H7725\">שׁלב</h>), <r v=\"Num.27.14\"></r> (<h n=\"H4808\">מְרִיבָה</h>), <r v=\"Job.23.13\"></r> (<h n=\"H7947\">שׁוּב</h> hi.)*;]</e> </et> <s n=\"1.\"><b>to fall against</b> or <b>upon</b> (Arist., Polyb.).</s> <s n=\"2.\"><b>to strive against</b>, <b>resist</b> (Arist.): c. dat., <r v=\"Acts.7.51\"></r>.</s>"},"G429":{"l":"ἀνευρίσκω","o":2,"ar":"<f>** <o>ἀν-ευρίσκω</o></f> <s><b>وجد</b> بعد البحث، <b>اكتشف</b>: <r v=\"Luke.2.16\"></r>، <r v=\"Acts.21.4\"></r>.†</s>","en":"<f>** <o>ἀν-ευρίσκω</o></f> <et> <e t=\"derivation\">(<x><g>ἀνά</g></x>, <x><g>εὑρίσκω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.3.14\"></r>*;]</e> </et> <s><b>to find out</b> by search, <b>discover</b> (v. Field, <i>Notes</i>, 47 f.): <r v=\"Luke.2.16\"></r>, <r v=\"Acts.21.4\"></r>.†</s>"},"G449":{"l":"ἄνιπτος","o":2,"ar":"<f>* <o>ἄνιπτος</o>، <g>-ον</g></f> <s><b>غير مغسول</b>: <r v=\"Matt.15.20\"></r>، <r v=\"Mark.7.2\"></r> (قارن <r v=\"Mark.7.5\"></r>).†</s>","en":"<f>* <o>ἄνιπτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>ἀ.</g> neg., <x><g>νίπτω</g></x>),</e> </et> <s><b>unwashed</b>: <r v=\"Matt.15.20\"></r>, <r v=\"Mark.7.2\"></r> (<r v=\"Mark.7.5\"></r> Rec).†</s>"}});A.got[4]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});